--
-- Table structure for table `activity_logs`
--

CREATE TABLE `activity_logs` (
  `id` bigint(20) UNSIGNED NOT NULL COMMENT 'شناسه یکتا لاگ فعالیت',
  `user_id` bigint(20) UNSIGNED NOT NULL COMMENT 'شناسه کاربری که این نقش را ایجاد کرده',
  `activity_type` varchar(255) NOT NULL COMMENT 'نوع فعالیت (مثل ورود به سیستم، بروزرسانی، حذف، مشاهده و...)',
  `description` text DEFAULT NULL COMMENT 'توضیحات مربوط به فعالیت',
  `ip_address` varchar(255) DEFAULT NULL COMMENT 'آدرس IP کاربر که فعالیت را انجام داده',
  `browser` varchar(255) DEFAULT NULL COMMENT 'مرورگر کاربر',
  `device` varchar(255) DEFAULT NULL COMMENT 'نوع دستگاه کاربر (موبایل، دسکتاپ و...)',
  `activity_time` timestamp NOT NULL DEFAULT current_timestamp() COMMENT 'زمان انجام فعالیت',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `calendars`
--

CREATE TABLE `calendars` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `label` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `start` datetime NOT NULL,
  `end` datetime DEFAULT NULL,
  `all_day` tinyint(1) NOT NULL DEFAULT 0,
  `url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `location` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `guests` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

