--
-- Table structure for table `comments`
--

CREATE TABLE `comments` (
  `id` bigint(20) UNSIGNED NOT NULL COMMENT 'شناسه یکتا کامنت',
  `commentable_id` varchar(255) NOT NULL COMMENT 'شناسه مدل مرتبط با کامنت',
  `commentable_type` varchar(255) NOT NULL COMMENT 'نوع مدل مرتبط (مثلاً Post, Product و...)',
  `user_id` bigint(20) UNSIGNED NOT NULL COMMENT 'شناسه کاربری که این نقش را ایجاد کرده',
  `parent_id` bigint(20) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'شناسه کامنت والد برای ریپلای‌ها',
  `approved` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'وضعیت تأیید کامنت',
  `comment` text NOT NULL COMMENT 'متن کامل کامنت',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `commitments`
--

CREATE TABLE `commitments` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `title` text DEFAULT NULL COMMENT 'عنوان',
  `guarantee` text DEFAULT NULL COMMENT 'تاریخ',
  `status` int(10) UNSIGNED NOT NULL COMMENT 'وضعیت'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

