--
-- Table structure for table `financial_statements`
--

CREATE TABLE `financial_statements` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `project_id` bigint(20) UNSIGNED DEFAULT NULL COMMENT 'طرح ',
  `year` int(11) DEFAULT NULL,
  `month` int(11) DEFAULT NULL,
  `net_sales` varchar(255) DEFAULT NULL COMMENT 'فروش خالص ',
  `operating_revenue` varchar(255) DEFAULT NULL COMMENT 'درآمدهای عملیاتی ',
  `cogs_goods` varchar(255) DEFAULT NULL COMMENT 'بهای تمام شده کالای فروش رفته ',
  `cogs_services` varchar(255) DEFAULT NULL COMMENT 'بهای تمام شده خدمات ',
  `gross_profit` varchar(255) DEFAULT NULL COMMENT 'سود ناخالص ',
  `selling_general_admin_expense` varchar(255) DEFAULT NULL COMMENT 'هزینه های فروش ،اداری و عمومی ',
  `operating_loss` varchar(255) DEFAULT NULL COMMENT 'سود/زیان عملیاتی ',
  `financial_expense` varchar(255) DEFAULT NULL COMMENT 'هزینه های مالی ',
  `other_income` varchar(255) DEFAULT NULL COMMENT 'سایر درآمدها ',
  `non_operating_net` varchar(255) DEFAULT NULL COMMENT 'سایر درآمدها و هزینه های غیر عملیاتی ',
  `profit_before_tax` varchar(255) DEFAULT NULL COMMENT 'سود(زيان)  قبل از مالیات ',
  `income_tax_expense` varchar(255) DEFAULT NULL COMMENT 'هزینه مالیات بردرآمد ',
  `net_profit` varchar(255) DEFAULT NULL COMMENT 'سود(زيان) خالص ',
  `tangible_fixed_assets` varchar(255) DEFAULT NULL COMMENT 'دارایی‌های ثابت مشهود ',
  `intangible_assets` varchar(255) DEFAULT NULL COMMENT 'دارایی‌های نامشهود ',
  `other_assets` varchar(255) DEFAULT NULL COMMENT 'سایر دارایی ها ',
  `total_non_current_assets` varchar(255) DEFAULT NULL COMMENT 'جمع دارایی‌های غير جاري ',
  `prepayments` varchar(255) DEFAULT NULL COMMENT 'پیش پرداخت‌ها ',
  `inventory` varchar(255) DEFAULT NULL COMMENT 'موجودی مواد وکالا ',
  `trade_receivables` varchar(255) DEFAULT NULL COMMENT 'دریافتنی‌های تجاری و سایر دریافتنی‌ها  ',
  `other_receivables` varchar(255) DEFAULT NULL COMMENT 'موجودي نقد ',
  `cash_and_equivalents` varchar(255) DEFAULT NULL COMMENT 'جمع دارایي‌هاي جاري ',
  `total_current_assets` varchar(255) DEFAULT NULL COMMENT 'جمع دارایی‌ها جاری',
  `total_assets` varchar(255) DEFAULT NULL COMMENT 'مجموع دارایی ها',
  `capital` varchar(255) DEFAULT NULL COMMENT 'سرمایه ',
  `capital_in_progress` varchar(255) DEFAULT NULL COMMENT 'سرمایه در جریان',
  `legal_reserve` varchar(255) DEFAULT NULL COMMENT 'اندوخته قانونی',
  `retained_earnings` varchar(255) DEFAULT NULL COMMENT 'سود / زیان انباشته',
  `total_equity` varchar(255) DEFAULT NULL COMMENT 'جمع حقوق مالکانه',
  `long_term_rnd_payable` varchar(255) DEFAULT NULL COMMENT 'پرداختنی بلندمدت تحقیق و توسعه',
  `long_term_loans` varchar(255) DEFAULT NULL COMMENT 'تسهیلات مالی بلندمدت',
  `employee_benefit_reserve` varchar(255) DEFAULT NULL COMMENT 'ذخیره مزایای پایان خدمت',
  `total_non_current_liabilities` varchar(255) DEFAULT NULL COMMENT 'جمع بدهی‌های غیرجاری',
  `trade_payables` varchar(255) DEFAULT NULL COMMENT 'پرداختنی‌های تجاری',
  `tax_payable` varchar(255) DEFAULT NULL COMMENT 'مالیات پرداختنی ',
  `short_term_loans` varchar(255) DEFAULT NULL COMMENT 'تسهیلات مالی ',
  `advances_received` varchar(255) DEFAULT NULL COMMENT 'پیش دریافت ها ',
  `total_current_liabilities` varchar(255) DEFAULT NULL COMMENT 'جمع بدهي‌هاي جاري ',
  `total_liabilities` varchar(255) DEFAULT NULL COMMENT 'جمع بدهي‌ها ',
  `total_equity_and_liabilities` varchar(255) DEFAULT NULL COMMENT 'جمع حقوق مالکانه و بدهی‌ها  ',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

