CREATE TABLE `investsteps` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `title` varchar(255) NOT NULL COMMENT 'عنوان مرحله',
  `description` varchar(255) NOT NULL COMMENT 'توضیحات الزام آور مرحله',
  `content` text NOT NULL COMMENT 'فرم های هر مرحله',
  `status` int(11) NOT NULL COMMENT 'وضعیت مرحله',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

