(3, NULL, 'امضای تفاهم نامه همکاری با محوریت فناوری های صنایع دریایی', NULL, NULL, 'امضای-تفاهم-نامه-همکاری-با-محوریت-فناوری-های-صنایع-دریایی', NULL, NULL, NULL, 'امضای تفاهم نامه همکاری با محوریت فناوری های صنایع دریایی ۱۴۰۳-۰۲-۲۵ به گزارش روابط عمومی سینا وی سی: تفاهم نامه همکاری فی مابین شرکت سینا وی سی و شرکت نو آوری صنایع دریایی با حضور مدیرعامل دو مجموعه به امضا رسید.', 'امضای تفاهم نامه همکاری با محوریت فناوری های صنایع دریایی ۱۴۰۳-۰۲-۲۵ به گزارش روابط عمومی سینا وی سی: تفاهم نامه همکاری فی مابین شرکت سینا وی سی و شرکت نو آوری صنایع دریایی با حضور مدیرعامل دو مجموعه به امضا رسید.', 4, NULL, '2024-05-13 20:30:00', '2024-05-13 20:30:00'),
(4, NULL, 'امضای سند همکاری سینا وی سی و پارک علم و فناوری قزوین', NULL, NULL, 'امضای-سند-همکاری-سینا-وی-سی-و-پارک-علم-و-فناوری-قزوین', NULL, NULL, NULL, 'امضای سند همکاری سینا وی سی و پارک علم و فناوری قزوین ۱۴۰۳-۰۲-۱۱ در حاشیه ششمین نمایشگاه بین‌المللی توانمندی‌های صادراتی IRAN EXPO 2024 سینا وی سی و پارک علم و فناوری قزوین تفاهم نامه همکاری امضا کردند.', 'امضای سند همکاری سینا وی سی و پارک علم و فناوری قزوین ۱۴۰۳-۰۲-۱۱ در حاشیه ششمین نمایشگاه بین‌المللی توانمندی‌های صادراتی IRAN EXPO 2024 سینا وی سی و پارک علم و فناوری قزوین تفاهم نامه همکاری امضا کردند.', 4, NULL, '2024-04-29 20:30:00', '2024-04-29 20:30:00'),
(5, NULL, 'امضا تفاهم نامه همکاری بین سینا وی سی و بیمه سینا', NULL, NULL, 'امضا-تفاهم-نامه-همکاری-بین-سینا-وی-سی-و-بیمه-سینا', NULL, NULL, NULL, 'امضا تفاهم نامه همکاری بین سینا وی سی و بیمه سینا ۱۴۰۲-۱۰-۰۵ این تفاهم نامه با هدف تقویت همکاری، هم افزایی، ارتقاء توانمندی تخصصی و به اشتراک گذاری دانش بومی در جهت پیشبرد اهداف توسعه ای با استفاده از ظرفیت های دانشی طرفین منعقد گردید', 'امضا تفاهم نامه همکاری بین سینا وی سی و بیمه سینا ۱۴۰۲-۱۰-۰۵ این تفاهم نامه با هدف تقویت همکاری، هم افزایی، ارتقاء توانمندی تخصصی و به اشتراک گذاری دانش بومی در جهت پیشبرد اهداف توسعه ای با استفاده از ظرفیت های دانشی طرفین منعقد گردید', 4, NULL, '2023-12-25 20:30:00', '2023-12-25 20:30:00'),
(6, NULL, 'انعقاد تفاهم‌نامه مشترک شرکت توسعه دانش بنیان سینا و کانون کارگزاران بورس و اوراق بهادار', NULL, NULL, 'انعقاد-تفاهم‌نامه-مشترک-شرکت-توسعه-دانش-بنیان-سینا-و-کانون-کارگزاران-بورس-و-اوراق-بهادار', NULL, NULL, NULL, 'انعقاد تفاهم‌نامه مشترک شرکت توسعه دانش بنیان سینا و کانون کارگزاران بورس و اوراق بهادار ۱۴۰۲-۰۹-۰۸ امروز کانون کارگزاران بورس و اوراق بهادار با امضای تفاهم نامه‌ای مشترک، پل ارتباطی بنیاد مستضعفان با بازار سرمایه شد.', 'انعقاد تفاهم‌نامه مشترک شرکت توسعه دانش بنیان سینا و کانون کارگزاران بورس و اوراق بهادار ۱۴۰۲-۰۹-۰۸ امروز کانون کارگزاران بورس و اوراق بهادار با امضای تفاهم نامه‌ای مشترک، پل ارتباطی بنیاد مستضعفان با بازار سرمایه شد.', 4, NULL, '2023-11-28 20:30:00', '2023-11-28 20:30:00'),
(7, NULL, 'انعقاد تفاهم نامه همکاری سینا وی سی و انجمن شرکت های حمل و نقل ریلی', NULL, NULL, 'انعقاد-تفاهم-نامه-همکاری-سینا-وی-سی-و-انجمن-شرکت-های-حمل-و-نقل-ریلی', NULL, NULL, NULL, 'انعقاد تفاهم نامه همکاری سینا وی سی و انجمن شرکت های حمل و نقل ریلی ۱۴۰۲-۰۹-۰۱ این تفاهم نامه در راستای هم افزایی و همکاری های فیمابین در محل شرکت توسعه دانش بنیان سینا شکل گرفت.', 'انعقاد تفاهم نامه همکاری سینا وی سی و انجمن شرکت های حمل و نقل ریلی ۱۴۰۲-۰۹-۰۱ این تفاهم نامه در راستای هم افزایی و همکاری های فیمابین در محل شرکت توسعه دانش بنیان سینا شکل گرفت.', 4, NULL, '2023-11-21 20:30:00', '2023-11-21 20:30:00'),
(8, NULL, 'بازدید از مرکز پردازش پیشرفته دیجی‌کالا؛ الگویی نوین در انبارداری و لجستیک', NULL, NULL, 'بازدید-از-مرکز-پردازش-پیشرفته-دیجیکالا؛-الگویی-نوین-در-انبارداری-و-لجستیک', 'site/posts/featured/LTLx9KAGn9U5vopm04H2R6145JJX2CxQKDuLQoFz.jpg', NULL, '[{\"path\":\"posts\\/gallery\\/Oe7KBzMYIpEAtHsAWZmD33leRPYOuunUvYWYaOJu.jpg\",\"type\":\"image\",\"name\":\"\\u062a\\u0648\\u0633\\u0639\\u0647-\\u062f\\u0627\\u0634\\u0646-\\u0628\\u0646\\u06cc\\u0627\\u0646-\\u0633\\u06cc\\u0646\\u0627-\\u062f\\u06cc\\u062c\\u06cc-\\u06a9\\u0627\\u0644\\u0627-\\u0627\\u0646\\u0628\\u0627\\u0631-\\u062f\\u0627\\u0646\\u0634.jpg\"},{\"path\":\"posts\\/gallery\\/S4BeiBYdwcsxXpr8G0ofkGKP5QgD0lNJF8Z28peE.jpg\",\"type\":\"image\",\"name\":\"\\u062a\\u0648\\u0633\\u0639\\u0647-\\u062f\\u0627\\u0646\\u0634-\\u0628\\u0646\\u06cc\\u0627\\u0646-\\u0633\\u06cc\\u0646\\u0627-\\u0645\\u062d\\u0645\\u062f-\\u062d\\u0633\\u06cc\\u0646-\\u062f\\u06cc\\u0648\\u0627\\u0646-\\u0628\\u06cc\\u06af\\u06cc-\\u0627\\u062d\\u0633\\u0627\\u0646-\\u06a9\\u0647\\u0646-\\u0631\\u0627\\u0632-\\u062f\\u06cc\\u062c\\u06cc\\u06a9\\u0627\\u0644\\u0627.jpg\"},{\"path\":\"posts\\/gallery\\/lnUhTPeCa7Ht0ZNrE84TFhqZ1PiA42dpyrXtJPUq.jpg\",\"type\":\"image\",\"name\":\"\\u0633\\u06cc\\u0646\\u0627-\\u0648\\u06cc-\\u0633\\u06cc-\\u062f\\u06cc\\u062c\\u06cc-\\u06a9\\u0627\\u0644\\u0627.jpg\"}]', 'جمعی از مدیران و کارشناسان سینا وی سی از مرکز پردازش و انبار شرکت دیجی‌کالا در شهرک دانش بازدید کردند. این بازدید با هدف آشنایی با فرآیندهای انبارداری و لجستیک دیجی‌کالا و بررسی امکانات، فناوری ها و دانش‌ به‌کاررفته در این مجموعه صورت گرفت.', '<p>بازدید از مرکز پردازش پیشرفته دیجی‌کالا؛ الگویی نوین در انبارداری و لجستیک</p><p>جمعی از مدیران و کارشناسان سینا وی سی از مرکز پردازش و انبار شرکت دیجی‌کالا در شهرک دانش بازدید کردند. این بازدید با هدف آشنایی با فرآیندهای انبارداری و لجستیک دیجی‌کالا و بررسی امکانات، فناوری ها و دانش‌ به‌کاررفته در این مجموعه صورت گرفت.</p><p>در جریان این بازدید، اعضاء با مراحل مختلف انبارداری، از دریافت کالا تا پردازش و ارسال سفارش‌ها، آشنا شدند. مرکز پردازش دانش دیجی‌کالا با مساحتی بالغ بر ۵۰ هزار مترمربع، یکی از بزرگ‌ترین مراکز پردازش در خاورمیانه محسوب می‌شود و ظرفیت انبارش بیش از ۵ میلیون کالا و پردازش ۵۰۰ هزار کالا در روز را داراست.</p><p>دیجی‌کالا با بهره‌گیری از فناوری‌های پیشرفته در حوزه انبارداری و لجستیک، فرآیندهای خود را به‌صورت بهینه مدیریت می‌کند. این شرکت دارای سه مرکز مجزا برای انبارداری در تهران است که شامل مرکز دانش، مرکز اتحاد و مرکز فتح می‌شود. همچنین، دیجی‌کالا با ایجاد انبارهای سیار در تهران و برخی شهرستان‌ها، امکان تحویل سریع‌تر کالاها را فراهم کرده است. در این بازدید، مدیران دیجی‌کالا توضیحاتی در مورد سیستم‌های مدیریت موجودی، فرآیندهای بسته‌بندی و ارسال کالا، و نحوه همکاری با فروشندگان ارائه دادند. همچنین، به برنامه‌های توسعه‌ای دیجی‌کالا در زمینه افزایش ظرفیت انبارداری و بهبود خدمات به مشتریان اشاره شد.</p>', 4, NULL, '2025-01-05 20:30:00', '2026-05-26 14:53:57'),
(9, NULL, 'بازدید از پروژه هوشمندسازی کشاورزی شرکت رایان آروین', NULL, NULL, 'بازدید-از-پروژه-هوشمندسازی-کشاورزی-شرکت-رایان-آروین', 'site/posts/featured/PzMTHg4SPY9VmSTbXFB1FsUtWxaEly3tfeK9UUyQ.jpg', NULL, '[{\"path\":\"posts\\/gallery\\/3bRxJPthfKvr3hq2oG0TFPuRqX20NFlm5fvDn5dV.jpg\",\"type\":\"image\",\"name\":\"IMG_20241113_151520_934.jpg\"},{\"path\":\"posts\\/gallery\\/dOVQ4ZJFCxLYZia9kD6G4N4oMzK13cjTDEiJ7OH7.jpg\",\"type\":\"image\",\"name\":\"IMG_20241113_151527_688.jpg\"}]', 'بازدید مدیرعامل و جمعی از همکاران شرکت توسعه دانش‌بنیان سینا از پروژه هوشمندسازی کشاورزی شرکت رایان آروین در مزرعه شرکت کشاورزی و دامپروری چالتاسیان صورت پذیرفت.', '<p><span style=\"color: rgb(67, 84, 106);\">بازدید از پروژه هوشمندسازی کشاورزی شرکت رایان آروین الگوریتم. بازدید مدیرعامل و جمعی از همکاران شرکت توسعه دانش‌بنیان سینا از پروژه هوشمندسازی کشاورزی شرکت رایان آروین در مزرعه شرکت کشاورزی و دامپروری چالتاسیان صورت پذیرفت.شرکت رایان آروین الگوریتم، یکی از شرکت‌های پرتفوی سینا وی‌سی می باشد که در زمینه مدیریت هوشمند آبیاری مزارع فعالیت می‌کند. این بازدید در راستای ارزیابی عملکرد سیستم‌های هوشمند آبیاری در محیط واقعی مزرعه و بررسی فرصت‌های همکاری بیشتر بود.در حاشیه این بازدید، نمایندگان سینا وی‌سی با مدیر بخش کشاورزی شرکت چالتاسیان دیدار و گفتگو کردند. در این نشست، طرفین ضمن معرفی ظرفیت‌ها و توانمندی‌های خود، به بررسی اثربخشی سیستم هوشمند آبیاری رایان آروین و سامانه سما کنترل در مزرعه چالتاسیان پرداختند. همچنین، معضلات موجود در حوزه کشاورزی و راهکارهای فناورانه برای حل این چالش‌ها مورد بحث و تبادل نظر قرار گرفت.</span></p>', 4, NULL, '2024-11-12 20:30:00', '2026-05-26 15:08:37'),
(10, NULL, 'بازدید از کارخانه پارس مینو: بزرگترین و با قدمت‌ترین کارخانه تولید تنقلات و خوراکی', NULL, NULL, 'بازدید-از-کارخانه-پارس-مینو-بزرگترین-و-با-قدمتترین-کارخانه-تولید-تنقلات-و-خوراکی', 'site/posts/featured/fnbtSCGOhu4M6QvRXVMpb1dei9MDP8Z4LlsK6YNi.jpg', NULL, '[{\"path\":\"posts\\/gallery\\/ZHrkt1OIfRRqdfSXolWbMCSKfQjzVrBsMr1ZyEEP.jpg\",\"type\":\"image\",\"name\":\"\\u062a\\u0648\\u0633\\u0639\\u0647-\\u062f\\u0627\\u0646\\u0634-\\u0628\\u0646\\u06cc\\u0627\\u0646-\\u0633\\u06cc\\u0646\\u0627-\\u06a9\\u0627\\u0631\\u062e\\u0627\\u0646\\u0647-\\u0645\\u06cc\\u0646\\u0648-\\u067e\\u0627\\u0631\\u0633-\\u0645\\u06cc\\u0646\\u0648.jpg\"}]', 'جمعی از مدیران و کارشناسان شرکت توسعه دانش بنیان سینا به عنوان بازوی سرمایه گذاری خطر پذیر بنیاد مستضعفان از کارخانه پارس مینو دیداری داشتند که تلفیقی از اصالت، فناوری و نوآوری در صنعت خوراکی ایران را به نمایش گذاشت.', '<p><span style=\"color: rgb(67, 84, 106);\">&nbsp;جمعی از مدیران و کارشناسان شرکت توسعه دانش بنیان سینا به عنوان بازوی سرمایه گذاری خطر پذیر بنیاد مستضعفان از کارخانه پارس مینو دیداری داشتند که تلفیقی از اصالت، فناوری و نوآوری در صنعت خوراکی ایران را به نمایش گذاشت. این بازدید، نه تنها فرصتی برای آشنایی عمیق با فرآیندهای پیشرفته تولید و استانداردهای کیفی بی‌نظیر این مجموعه فراهم آورد، بلکه به عنوان الگویی برای توسعه پایدار در صنعت غذایی کشور به شمار می‌آید.در طول این تجربه، مهمانان با مراحل دقیق و حرفه‌ای تولید، از آماده‌سازی مواد اولیه گرفته تا خطوط بسته‌بندی، که شامل تولید شکلات‌های لذیذ، بیسکویت‌های خوش‌طعم و آدامس های متنوع می‌شود، آشنا شدند. استفاده از فناوری‌های نوین در کنار تجهیزات پیشرفته در کارخانه پارس مینو، نشانگر تعهد این مجموعه به ارائه محصولاتی با بالاترین استانداردهای جهانی و بهبود مستمر فرآیندهای تولید است.</span></p><p><span style=\"color: rgb(67, 84, 106);\">کارخانه پارس مینو با دارا بودن زیرساخت‌های گسترده و سرمایه‌گذاری‌های کلان در زمینه تکنولوژی، به عنوان نمادی از پیشگامی در صنعت خوراکی و تنقلات در ایران شناخته می‌شود. مدیران کارخانه در خلال بازدید، با ارائه توضیحات جامع پیرامون سیستم‌های کنترل کیفیت، فرآیندهای بسته‌بندی و راهکارهای بازاریابی نوین، به شفافیت عملیاتی و استراتژی‌های توسعه‌ای اشاره کردند.</span></p><p><span style=\"color: rgb(67, 84, 106);\">همچنین، برنامه‌های توسعه‌ای کارخانه در زمینه تنوع‌بخشی به محصولات و بهبود مستمر فرآیندهای تولید، نمونه‌ای بارز از هماهنگی و هم‌افزایی میان تیم‌های فنی و مدیریتی این مجموعه را به نمایش گذاشت. این دیدار سرشار از تجربیات آموزنده و نکات کلیدی مدیریتی، تأکیدی است بر اهمیت سرمایه‌گذاری در فناوری‌های نوین و نوآوری‌های صنعتی حتی در شرکتی با اصالت و قدمت به عنوان محرک اصلی رشد و توسعه پایدار در عرصه تنقلات و خوراکی می باشد.</span></p><p><span style=\"color: rgb(67, 84, 106);\">در نهایت، بازدید از کارخانه پارس مینو به عنوان نقطه عطفی در ارتقای استانداردهای صنعتی و نمونه‌ای از تعهد به کیفیت و نوآوری، موجبات امیدواری و الهام‌بخشی برای مدیران و کارشناسان این مجموعه سرمایه گذار داشت.</span></p>', 4, NULL, '2025-02-23 20:30:00', '2026-05-26 14:38:27'),
(11, NULL, 'بازدید مدیران شرکت توسعه دانش بنیان سینا از شرکت مهندسی و ساخت برق و کنترل مپنا(مکو)', NULL, NULL, 'بازدید-مدیران-شرکت-توسعه-دانش-بنیان-سینا-از-شرکت-مهندسی-و-ساخت-برق-و-کنترل-مپنامکو', 'site/posts/featured/TZZOldxBbJz6AOdMKwY98X1YQDh1EEeHJ5KipdGa.jpg', NULL, '[{\"path\":\"posts\\/gallery\\/nGFkcYHokqfcTZTqnZwmFamJfFzdJhQgaf7615I4.png\",\"type\":\"image\",\"name\":\"3.png\"},{\"path\":\"posts\\/gallery\\/gCNI6keU1ALWzqkMnuFpMJ7kB7TDcbQD9kF3jmcE.jpg\",\"type\":\"image\",\"name\":\"4.jpg\"},{\"path\":\"posts\\/gallery\\/sGs0tJjG1oJyu8ndogy8pB0Qyz7PZuYCSLSfFmbO.jpg\",\"type\":\"image\",\"name\":\"1.jpg\"}]', 'در راستای گسترش تعاملات فناورانه و آشنایی با ظرفیت های صنعتی کشور،جمعی از مدیران و کارشناسان شرکت توسعه دانش بنیان سینا از بخش های مختلف شرکت مهندسی و ساخت برق و کنترل مپنا(مکو) بازدید نمودند.', '<p>در راستای گسترش تعاملات فناورانه و آشنایی با ظرفیت های صنعتی کشور،جمعی از مدیران و کارشناسان شرکت توسعه دانش بنیان سینا از بخش های مختلف شرکت مهندسی و ساخت برق و کنترل مپنا(مکو)بازدید نمودند.</p><p>این بازدید با هدف بررسی توانمندی های تولیدی،دستاوردهای فناورانه و ساختار مدیریتی گروه مکو انجام شد.در جریان این بازدید هیئت اعزامی بافرآیندهای تخصصی تولید و حوزه های مختلف فعالیت این گروه صنعتی از نزدیک آشنا شدند.</p><p>در توضیحات ارائه شده از سوی مدیران مکو،به نقش این مجموعه در زنجیره تامین انرژی کشور اشاره شد؛ زنجیره ای کامل که با تکیه بر دانش بومی و توان متخصصان ایرانی شکل گرفته وشامل تولید انواع بردهای الکترونیکی،شارژرها، تابلوهای برق نیروگاهی،تجهیزات برق خودروهای برقی،توربین ها و سایر محصولات صنعتی است.</p><p>همچنین نمایندگان مپنا گزارشی از فعالیت های گروه در حوزه های نیروگاه ها،انرژی ،نفت و گاز،حمل و نقل ریلی و پروژه های نوآورانه فناورانه ارائه کردند.در ادامه،نمایندگان شرکت توسعه دانش بنیان سینا ضمن طرح پرسش هایی درباره مدل های مدیریتی، فرآیندهای مهندسی و سیستم های کنترل کیفیت،بر اهمیت همکاری های فناورانه و تبادل تجربیات میان شرکت های دانش بنیان و صنایع مادر تاکید کردند.</p><p>این بازدید در فضایی صمیمی و تخصصی برگزار شد و زمینه ساز تقویت ارتباطات میان بخش خصوصی و صنایع پیشرو کشور در مسیر تحقق اقتصاد دانش بنیان شد.</p>', 4, NULL, '2025-11-10 20:30:00', '2026-05-26 14:19:39'),
(12, NULL, 'بازدید مدیران و کارشناسان شرکت توسعه دانش‌بنیان سینا از کارخانه تولید خوراک دام فرتاک جوجه تیمره', NULL, NULL, 'بازدید-مدیران-و-کارشناسان-شرکت-توسعه-دانشبنیان-سینا-از-کارخانه-تولید-خوراک-دام-فرتاک-جوجه-تیمره', 'site/posts/featured/NQ8KwyBIoKvh9RwlZPtCnhgOZTLDt6P70HEoETT8.jpg', NULL, '[]', 'جمعی از مدیران و کارشناسان شرکت توسعه دانش‌بنیان سینا در راستای ارزیابی عملکرد و بررسی روند پیشرفت شرکت فرتاک جوجه تیمره، از کارخانه تولید خوراک دام این مجموعه در شهرستان خمین بازدید کردند.', '<p>بازدید مدیران و کارشناسان شرکت توسعه دانش‌بنیان سینا از کارخانه تولید خوراک دام فرتاک جوجه تیمره</p><p>جمعی از مدیران و کارشناسان شرکت توسعه دانش‌بنیان سینا در راستای ارزیابی عملکرد و بررسی روند پیشرفت شرکت فرتاک جوجه تیمره، از کارخانه تولید خوراک دام این مجموعه در شهرستان خمین بازدید کردند.</p><p>این بازدید که با هدف ارتقای تعاملات و بررسی امکانات و ظرفیت‌های تولیدی انجام شد، فرصتی برای تبادل نظر و آشنایی نزدیک‌تر با فرآیندها و دستاوردهای این شرکت فراهم آورد.</p><p>پس از این بازدید، جلسه‌ای با حضور هیئت مدیره شرکت فرتاک جوجه تیمره برگزار شد. در این نشست، موضوعات مطرح‌شده در بازدید بررسی گردید و تصمیمات مهمی در راستای بهبود عملکرد و توسعه فعالیت‌های مشترک اتخاذ شد.</p><p>این تعاملات گامی مهم در جهت تقویت همکاری‌های علمی و صنعتی و تحقق اهداف مشترک شرکت‌های دانش‌بنیان است.</p>', 4, NULL, '2025-01-04 20:30:00', '2026-05-26 14:57:08'),
(13, NULL, 'بازدید مدیرعامل و کمیته سرمایه‌گذاری سینا وی سی از مرکز رشد دارویی دانشگاه تهران صورت پذیرفت', NULL, NULL, 'بازدید-مدیرعامل-و-کمیته-سرمایهگذاری-سینا-وی-سی-از-مرکز-رشد-دارویی-دانشگاه-تهران-صورت-پذیرفت', 'site/posts/featured/4VTt2Pb0hhLN5e06JirdxcZJRDqQZMkKnxCbRJRB.jpg', NULL, '[{\"path\":\"posts\\/gallery\\/PUP7Gsgnjs117Ot1O0RQK9PreKHXYemOeEZhNmav.jpg\",\"type\":\"image\",\"name\":\"\\u06cc\\u0627\\u0633\\u0631-\\u062e\\u0627\\u0646\\u06cc-\\u0633\\u0631\\u0645\\u0627\\u06cc\\u0647-\\u06af\\u0630\\u0627\\u0631.jpg\"},{\"path\":\"posts\\/gallery\\/nLY8pkMuxuWT4mbZfERgQPOz0Lvr6UiTtxhrWH5I.jpg\",\"type\":\"image\",\"name\":\"\\u06cc\\u0627\\u0633\\u0631-\\u062e\\u0627\\u0646\\u06cc-\\u06a9\\u0634\\u0645\\u0631\\u0632\\u06cc-\\u0633\\u06cc\\u0646\\u0627-\\u0648\\u06cc-\\u0633\\u06cc.jpg\"},{\"path\":\"posts\\/gallery\\/s0myxfG1oFEwbjMF69GFlx7WhDFyGoLuuCyThXns.jpg\",\"type\":\"image\",\"name\":\"\\u062a\\u0648\\u0633\\u0639\\u0647-\\u062f\\u0627\\u0646\\u0634-\\u0628\\u0646\\u06cc\\u0627\\u0646-\\u0633\\u06cc\\u0646\\u0627-\\u06cc\\u0627\\u0633\\u0631-\\u062e\\u0627\\u0646\\u06cc-1.jpg\"},{\"path\":\"posts\\/gallery\\/NJmTW89oAqBxrqJ8Dkhvl8rUwiavnln1RAu3bq9v.jpg\",\"type\":\"image\",\"name\":\"\\u0633\\u0631\\u0645\\u0627\\u06cc\\u0647-\\u06af\\u0630\\u0627\\u0631\\u06cc-\\u062a\\u0648\\u0633\\u0639\\u0647-\\u062f\\u0627\\u0646\\u0634-\\u0628\\u0646\\u06cc\\u0627\\u0646-\\u0633\\u06cc\\u0646\\u0627.jpg\"},{\"path\":\"posts\\/gallery\\/KN1p0VKlmv9ZPNYmboJd0pgPeJIHVST6QoquP0wd.jpg\",\"type\":\"image\",\"name\":\"\\u0633\\u06cc\\u0646\\u0627-\\u0648\\u06cc-\\u0633\\u06cc.jpg\"}]', 'در این بازدید مدیر محترم مرکز رشد فناوری های دارویی دانشگاه تهران، دکتر بیگلر به ارائه گزارش و دستاوردهای این مرکز پرداختند.', '<p>بازدید مدیرعامل و کمیته سرمایه‌گذاری سینا وی سی از مرکز رشد دارویی دانشگاه تهران صورت پذیرفت</p><p>در این بازدید مدیر محترم مرکز رشد فناوری های دارویی دانشگاه تهران، دکتر&nbsp;بیگلر به ارائه گزارش و&nbsp;دستاوردهای این مرکز پرداختند.</p><p>در ادامه جلسه، شرکت‌های مستقر در این مرکز ضمن معرفی و ارائه محصولات خود، سئوالاتی را در خصوص نحوه سرمایه گذاری سیناوی سی مطرح نمودند.</p><p>همچنین مهندس یاسر خانی مدیرعامل شرکت توسعه دانش بنیان سینا نیز به معرفی خدمات قابل ارائه و شرایط سرمایه گذاری سینا وی سی پرداختند.&nbsp;وی خاطر نشان کرد ، با وجود اینکه سرمایه‌گذاری در صنعت دارو در اولویت‌ شرکت سرمایه گذاری سینا وی سی نمی‌باشد ولیکن در صورتی جزو تامین نیازمندی های راهبردی کشور و فناوری‌های پیشرفته و آینده ساز باشد، سینا وی سی آمادگی خود را جهت مذاکره با شرکت ها اعلام می دارد.</p><p>در حاشیه این بازدید از محوطه کارگاه ها و آزمایشگاه ها و تولیدات این مرکز بازدید به عمل آمد.</p>', 4, NULL, '2024-12-15 20:30:00', '2026-05-26 15:01:20'),
(14, NULL, 'بررسی پیوست فناوری مدل آبادانی و پیشرفت مناطق محروم', NULL, NULL, 'بررسی-پیوست-فناوری-مدل-آبادانی-و-پیشرفت-مناطق-محروم', NULL, NULL, NULL, 'بررسی پیوست فناوری مدل آبادانی و پیشرفت مناطق محروم ۱۴۰۲-۰۳-۲۰ شرکت توسعه دانش بنیان سینا در جلسه‌ای مشترک با مدیر کل آبادانی و پیشرفت بنیاد مسکن انقلاب اسلامی، نمایندگان وزارت دفاع و بنیاد علوی به تبادل نظر و گزارش پیرامون اقدامات انجام شده پرداختند', 'بررسی پیوست فناوری مدل آبادانی و پیشرفت مناطق محروم ۱۴۰۲-۰۳-۲۰ شرکت توسعه دانش بنیان سینا در جلسه‌ای مشترک با مدیر کل آبادانی و پیشرفت بنیاد مسکن انقلاب اسلامی، نمایندگان وزارت دفاع و بنیاد علوی به تبادل نظر و گزارش پیرامون اقدامات انجام شده پرداختند.', 4, NULL, '2023-06-09 20:30:00', '2023-06-09 20:30:00'),
(15, NULL, 'برگزاری نشست خبری رویداد پل سرمایه گذاری فراگیری و فناوری مالی', NULL, NULL, 'برگزاری-نشست-خبری-رویداد-پل-سرمایه-گذاری-فراگیری-و-فناوری-مالی', NULL, NULL, NULL, 'برگزاری نشست خبری رویداد پل سرمایه گذاری فراگیری و فناوری مالی ۱۴۰۲-۱۰-۰۵ نشست خبری سومین رویداد پل سرمایه گذاری در حوزه فناوری های مالی در محل شرکت توسعه دانش بنیان سینا با حضور مدیرعامل این شرکت و خبرنگاران خبرگذاری های رسمی کشور و همچنین روزنامه ن', 'برگزاری نشست خبری رویداد پل سرمایه گذاری فراگیری و فناوری مالی ۱۴۰۲-۱۰-۰۵ نشست خبری سومین رویداد پل سرمایه گذاری در حوزه فناوری های مالی در محل شرکت توسعه دانش بنیان سینا با حضور مدیرعامل این شرکت و خبرنگاران خبرگذاری های رسمی کشور و همچنین روزنامه نگاران برگزار شد.', 4, NULL, '2023-12-25 20:30:00', '2023-12-25 20:30:00'),
(16, NULL, 'برگزاری کارگروه مشترک طرح های دریافتی حوزه عمران', NULL, NULL, 'برگزاری-کارگروه-مشترک-طرح-های-دریافتی-حوزه-عمران', NULL, NULL, NULL, 'برگزاری کارگروه مشترک طرح های دریافتی حوزه عمران ۱۴۰۲-۰۳-۲۰ کارگروه طرح های دریافتی حوزه عمران با هدف ارزیابی طرح های این حوزه با ارائه ی شرکت نوید ساختار بهینه، گروه تخصصی سازه و مقاوم سازی عملکرد، دفتر مدیریت پروژه و مدلسازی اطلاعات ساختمان شریف، م', 'برگزاری کارگروه مشترک طرح های دریافتی حوزه عمران ۱۴۰۲-۰۳-۲۰ کارگروه طرح های دریافتی حوزه عمران با هدف ارزیابی طرح های این حوزه با ارائه ی شرکت نوید ساختار بهینه، گروه تخصصی سازه و مقاوم سازی عملکرد، دفتر مدیریت پروژه و مدلسازی اطلاعات ساختمان شریف، مرکز مطالعات مهندسی سپاه در حوزه ی ساختمان و ارائه مدل بومی سازی میلگرد کامپوزیتی GFRP در تاریخ ۲۹ شهریور ماه برگزار شد.', 4, NULL, '2023-06-09 20:30:00', '2023-06-09 20:30:00'),
(17, NULL, 'برگزاری کمیته سرمایه گذاری شرکت توسعه دانش بنیان سینا', NULL, NULL, 'برگزاری-کمیته-سرمایه-گذاری-شرکت-توسعه-دانش-بنیان-سینا', 'site/posts/featured/l0laBH1Cs0sFLyyQyn2jYQWxpCo2LuOlNWqvpeZ4.jpg', NULL, '[]', 'شرکت توسعه دانش بنیان سینا(سینا وی سی) به منظور ارزیابی وضعیت موجود شرکت های پرتفوی خود جهت ایجاد توسعه بازار، اقدام به برگزاری جلسات کمیته سرمایه گذاری نمود.', '<p>شرکت توسعه دانش بنیان سینا(سینا وی سی) به منظور ارزیابی وضعیت موجود شرکت های پرتفوی خود جهت ایجاد توسعه بازار، اقدام به برگزاری جلسات کمیته سرمایه گذاری نمود. در طی این جلسه که مورخ 13 مرداد ماه تشکیل گردید،مدیران شرکت های پرتفو به ارائه گزارشی از نقاط قوت و ضعف کسب و کار خود پرداختند. هم چنین اعضای کمیته نیز که متشکل از مدیران و مشاوران سینا وی سی بوده ، ضمن ابراز خوشنودی از فعالیت های صورت گرفته، راه حل های پیش رو کسب و کار ر ا بیان نمودند.</p>', 4, NULL, '2025-08-11 20:30:00', '2026-05-26 14:27:41'),
(18, NULL, 'تاثیر نمایشگاه GITEX Global 2024 دبی در حوزه هوش مصنوعی', NULL, NULL, 'تاثیر-نمایشگاه-GITEX-Global-2024-دبی-در-حوزه-هوش-مصنوعی', NULL, NULL, NULL, 'تاثیر نمایشگاه GITEX Global 2024 دبی در حوزه هوش مصنوعی ۱۴۰۳-۰۸-۱۳ 2024 GITEX Global به عنوان بزرگترین نمایشگاه فناوری جهان در دبی با هدف ارائه جدیدترین و پیشرفته ترین فناوری ها و نوآوریها با تمرکز بر نقش تحول آفرین هوش مصنوعی در صنایع مختلف برگزار گ', 'تاثیر نمایشگاه GITEX Global 2024 دبی در حوزه هوش مصنوعی ۱۴۰۳-۰۸-۱۳ 2024 GITEX Global به عنوان بزرگترین نمایشگاه فناوری جهان در دبی با هدف ارائه جدیدترین و پیشرفته ترین فناوری ها و نوآوریها با تمرکز بر نقش تحول آفرین هوش مصنوعی در صنایع مختلف برگزار گردید این نمایشگاه به عنوان پلتفرمی برای تبادل دانش و تجربیات ایجاد همکاریهای تجاری و نمایش دستاوردهای جدید علمی و صنعتی عمل می کنند.', 4, NULL, '2024-11-02 20:30:00', '2024-11-02 20:30:00'),
(19, NULL, 'تشکیل جلسه کمیته ریسک شرکت توسعه دانش‌بنیان سینا با هدف مدیریت چالش‌ها', NULL, NULL, 'تشکیل-جلسه-کمیته-ریسک-شرکت-توسعه-دانشبنیان-سینا-با-هدف-مدیریت-چالشها', 'site/posts/featured/EjZ49Slr9sKIMNSrozmXwKMy6jgUtsdoqoFQtG02.jpg', NULL, '[{\"path\":\"posts\\/gallery\\/UeYY7WDilfRSl5kfcDe8ibYmA4ZdZKK9CAo6tyay.jpg\",\"type\":\"image\",\"name\":\"AM3A0080.jpg\"},{\"path\":\"posts\\/gallery\\/kZkzu3gt0yozUXeQ9RZ7hlBYYX24woh5cYy103p7.jpg\",\"type\":\"image\",\"name\":\"\\u062a\\u0648\\u0633\\u0639\\u0647-\\u062f\\u0627\\u0646\\u0634-\\u0628\\u0646\\u06cc\\u0627\\u0646-\\u0633\\u06cc\\u0646\\u0627-1.jpg\"}]', 'با هدف تقویت مدیریت پرتفوی سرمایه‌گذاری و نظارت بر ریسک‌های پیش رو، جلسه کمیته ریسک شرکت توسعه دانش‌بنیان سینا برگزار شد. در این نشست، راهکارهای کنترلی و پیشگیرانه برای چالش‌های پروژه‌های جاری تصویب و بر تداوم این جلسات جهت پایش مستمر تأکید گردید.', '<p><span style=\"color: rgb(67, 84, 106);\">در راستای بهبود فرآیند مدیریت پرتفوی سرمایه گذاری و تقویت نظارت بر ریسک ها و چالش های پیش رو، جلسه کمیته ریسک شرکت توسعه دانش‌بنیان سینا در تاریخ ۳۱ تیرماه با حضور اعضاء کمیته برگزار شد.</span></p><p><span style=\"color: rgb(67, 84, 106);\">در این جلسه، مهم‌ترین مسائل و ریسک‌های پیش‌روی پروژه‌های جاری شرکت مورد بررسی قرار گرفت و راهکارهای پیشگیرانه و کنترلی متناسب مصوب گردید. همچنین مقرر شد جلسات این کمیته به‌صورت مستمر با هدف شناسایی و پایش ریسک‌های پیش رو برگزار شود.</span></p>', 4, NULL, '2025-07-21 20:30:00', '2026-05-26 14:29:41'),
(20, NULL, 'تیزر ویدیویی سما کنترل؛ گامی نوین در کشاورزی هوشمند', NULL, NULL, 'تیزر-ویدیویی-سما-کنترل؛-گامی-نوین-در-کشاورزی-هوشمند', 'site/posts/featured/7IEHhXejhOtbORAClH3RCeg2XnKRWkZtUsSwxTyj.jpg', NULL, '[]', 'سما کنترل، محصولی دانش‌بنیان در حوزه کشاورزی هوشمند، با هدف توانمندسازی کشاورزان و افزایش بهره‌وری طراحی و تولید شده است. این سامانه با بهره‌گیری از فناوری‌های پیشرفته، امکاناتی همچون محاسبه نیاز دقیق آبیاری، تنظیم شرایط دما و رطوبت، تحلیل داده‌های هواشناسی و یادگیری عمیق داده‌ها را ارائه می‌دهد.', '<p>تیزر ویدیویی <a href=\"https://samacontrol.com/\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(18, 111, 230); background-color: transparent;\">سما کنترل</a>؛ گامی نوین در کشاورزی هوشمند</p><p>سما کنترل، محصولی دانش‌بنیان در حوزه کشاورزی هوشمند، با هدف توانمندسازی کشاورزان و افزایش بهره‌وری مزارع کشاورزی طراحی و راه اندازی شده است. این سامانه با بهره‌گیری از فناوری‌های پیشرفته، امکاناتی همچون محاسبه نیاز دقیق آبیاری، تنظیم شرایط دما و رطوبت، تحلیل داده‌های هواشناسی و یادگیری عمیق داده‌ها را ارائه می‌دهد. تیزر معرفی این فناوری را از دست ندهید!</p><p>#سماکنترل #کشاورزی_هوشمند #تکنولوژی #آبیاری_هوشمند #کشاورزی_پیشرفته</p>', 4, NULL, '2025-02-04 20:30:00', '2026-05-26 14:42:29'),
(21, NULL, 'تیزر ویدیو شرکت نفت آزمایان ژرف اندیش؛نوآوری در صنعت نفت', NULL, NULL, 'تیزر-ویدیو-شرکت-نفت-آزمایان-ژرف-اندیش؛نوآوری-در-صنعت-نفت', 'site/posts/featured/7rhNLZxjH4gDP4Bs28sTXstoDgr3JuzJrNxyPorT.jpg', NULL, '[]', 'با افتخار به معرفی شرکت نفت آزمایان ژرف اندیش، یک پیشرو در ارائه راهکارهای نوین صنعتی در سال 1398. این شرکت با تأیید وزارت علوم به عنوان “شرکت دانش بنیان”، متعهد به ارائه فناوری‌های پیشرفته‌ای نظیر سیستم مانتیورینگ پارامترهای حفاری (Drill Watch)، یونیت نمودارگیری از حفاری (Mud Logging Unit)، و سیستم تعمیرات پیشگیرانه (PMS) می‌باشد.', '<p>با افتخار به معرفی شرکت نفت آزمایان ژرف اندیش، یک پیشرو در ارائه راهکارهای نوین صنعتی در سال 1398. این شرکت با تأیید وزارت علوم به عنوان “شرکت دانش بنیان”، متعهد به ارائه فناوری‌های پیشرفته‌ای نظیر سیستم مانتیورینگ پارامترهای حفاری (Drill Watch)، یونیت نمودارگیری از حفاری (Mud Logging Unit)، و سیستم تعمیرات پیشگیرانه (PMS) می‌باشد. تمامی این محصولات با گواهی ثبت اختراع، توانسته‌اند صرفه‌جویی ارزی بالغ بر 5.5 میلیون دلار را به ارمغان آورند. همچنین خوشحالی ما دو چندان است که شرکت توسعه دانش بنیان سینا به عنوان سرمایه‌گذار اصلی ما، در این مسیر نوآورانه همراه ماست. به جمع ما بپیوندید و شاهد تحولاتی که در انتظار صنعت نفت و گاز است، باشید!</p>', 4, NULL, '2025-04-13 20:30:00', '2026-05-26 14:30:30'),
(22, NULL, 'جلسه ارزیابی عملکرد شرکت نفت آزمایان ژرف اندیش', NULL, NULL, 'جلسه-ارزیابی-عملکرد-شرکت-نفت-آزمایان-ژرف-اندیش', 'site/posts/featured/9fAJESlvNmkU9i8LDcwJH52JLUyjdC9yCrMJp5dq.jpg', NULL, '[]', 'این جلسه با حضور مدیران شرکت و اعضای کمیته ریسک برگزار گردید.در همین خصوص قراردادهای جاری، چالش های پیش رو مورد بحث قرار گرفت.', '<p>این جلسه با حضور مدیران شرکت و اعضای کمیته ریسک برگزار گردید.در همین خصوص قراردادهای جاری،چالش های پیش رو، مسائل فنی، وضعیت مالی و توسعه بازار طرح مورد بررسی و بحث قرارگرفت و درنهایت مقرر شد اقدامات لازم توسعه همکاری با شرکت حفاری شمال صورت پذیرفته و ضمن توسعه بازار در بخش خصوصی و نیمه دولتی، موانع پیش رو شرکت بابت تامین سرمایه در گردش دنبال شود.</p>', 4, NULL, '2025-09-02 20:30:00', '2026-05-26 14:26:03'),
