(39, NULL, 'معرفی شرکت داده پژوهان سدید سپاهان', NULL, NULL, 'معرفی-شرکت-داده-پژوهان-سدید-سپاهان', NULL, NULL, NULL, 'معرفی شرکت داده پژوهان سدید سپاهان ۱۴۰۳-۰۷-۲۸ شرکت داده پژوهان سدید سپاهان تحت برند فرش گره فعالیت حود را از سال 1395 در حوزه بافته‌های طبیعی، ارگانیک آغاز کرد.', 'معرفی شرکت داده پژوهان سدید سپاهان ۱۴۰۳-۰۷-۲۸ شرکت داده پژوهان سدید سپاهان تحت برند فرش گره فعالیت حود را از سال 1395 در حوزه بافته‌های طبیعی، ارگانیک آغاز کرد.', 4, NULL, '2024-10-18 20:30:00', '2024-10-18 20:30:00'),
(40, NULL, 'شرکت داده پژوهان مانا (نویسش)', NULL, NULL, 'شرکت-داده-پژوهان-مانا-(نویسش)', NULL, NULL, NULL, 'شرکت داده پژوهان مانا (نویسش) ۱۴۰۳-۰۷-۲۸ شرکت داده پژوهان مانا بر اساس نیاز جامعه کنولوژی و آی تی به محتوای حرفه‌ای، باکیفیت و دست اول و به‌منظور اتصال کارفرمایان و تولیدکنندگان محتوا در سال ۱۳۹۶ آغاز به کار کرد', 'شرکت داده پژوهان مانا (نویسش) ۱۴۰۳-۰۷-۲۸ شرکت داده پژوهان مانا بر اساس نیاز جامعه کنولوژی و آی تی به محتوای حرفه‌ای، باکیفیت و دست اول و به‌منظور اتصال کارفرمایان و تولیدکنندگان محتوا در سال ۱۳۹۶ آغاز به کار کرد', 4, NULL, '2024-10-18 20:30:00', '2024-10-18 20:30:00'),
(41, NULL, 'معرفی شرکت گسترش فناوری فروش هوشمند ویرا', NULL, NULL, 'معرفی-شرکت-گسترش-فناوری-فروش-هوشمند-ویرا', NULL, NULL, NULL, 'معرفی شرکت گسترش فناوری فروش هوشمند ویرا ۱۴۰۳-۰۷-۲۹ شرکت گسترش فناوری فروش هوشمند ویرا، با نام تجاری “باینو ” یک شرکت نوآور در زمینه فروشگاه‌های هوشمند بدون فروشنده است که از آبان سال ۱۳۹۶ شروع به فعالیت کرده است.', 'معرفی شرکت گسترش فناوری فروش هوشمند ویرا ۱۴۰۳-۰۷-۲۹ شرکت گسترش فناوری فروش هوشمند ویرا، با نام تجاری “باینو ” یک شرکت نوآور در زمینه فروشگاه‌های هوشمند بدون فروشنده است که از آبان سال ۱۳۹۶ شروع به فعالیت کرده است.', 4, NULL, '2024-10-19 20:30:00', '2024-10-19 20:30:00'),
(42, NULL, 'صنعت فین‌تک نیازمند توجه ویژه سیاستگذاران است', NULL, NULL, 'صنعت-فین‌تک-نیازمند-توجه-ویژه-سیاستگذاران-است', NULL, NULL, NULL, 'صنعت فین‌تک نیازمند توجه ویژه سیاستگذاران است ۱۴۰۲-۱۱-۱۵ در نشست علمی تخصصی سینا وی سی با مشارکت مرکز پژوهش‌های توسعه و آینده نگری مطرح شد: فعالیت‌های مالی اقتصادی از تکنولوژی فین‌تک عقب‌مانده است، مهم‌ترین نقش در فناوری‌های نوین مالی، فراگیری مالی ا', 'صنعت فین‌تک نیازمند توجه ویژه سیاستگذاران است ۱۴۰۲-۱۱-۱۵ در نشست علمی تخصصی سینا وی سی با مشارکت مرکز پژوهش‌های توسعه و آینده نگری مطرح شد: فعالیت‌های مالی اقتصادی از تکنولوژی فین‌تک عقب‌مانده است، مهم‌ترین نقش در فناوری‌های نوین مالی، فراگیری مالی است، تحت‌تأثیر هوش مصنوعی و بیگ دیتا چشم‌انداز ارائه خدمات فناوری مالی در آینده وسیع‌تر خواهد شد، از تنظیم‌گری به‌عنوان مهم‌ترین چالش در فناوری‌های نوین مالی یاد می‌شود.', 4, NULL, '2024-02-03 20:30:00', '2024-02-03 20:30:00'),
(43, NULL, 'فراخوان کارگزاران ارزشگذاری', NULL, NULL, 'فراخوان-کارگزاران-ارزشگذاری', NULL, NULL, NULL, 'فراخوان کارگزاران ارزشگذاری ۱۴۰۳-۰۸-۱۵ به اطلاع میرساند شرکت توسعه دانش بنیان سینا به عنوان یکی از شرکتهای فعال در حوزه سرمایه گذاری خطر پذیر، در نظر دارد نسبت به ارزشگذاری پورتفوی سرمایه گذاری خود اقدام نماید.', 'فراخوان کارگزاران ارزشگذاری ۱۴۰۳-۰۸-۱۵ به اطلاع میرساند شرکت توسعه دانش بنیان سینا به عنوان یکی از شرکتهای فعال در حوزه سرمایه گذاری خطر پذیر، در نظر دارد نسبت به ارزشگذاری پورتفوی سرمایه گذاری خود اقدام نماید.', 4, NULL, '2024-11-04 20:30:00', '2024-11-04 20:30:00'),
(44, NULL, 'مجمع عمومی عادی شرکت توسعه دانش بنیان سینا برای سال مالی منتهی به ۲۹ اسفند', NULL, NULL, 'مجمع-عمومی-عادی-شرکت-توسعه-دانش-بنیان-سینا-برای-سال-مالی-منتهی-به-۲۹-اسفند', NULL, NULL, NULL, 'مجمع عمومی عادی شرکت توسعه دانش بنیان سینا برای سال مالی منتهی به ۲۹ اسفند ۱۴۰۳-۰۸-۱۳ مجمع عمومی عادی شرکت توسعه دانش بنیان سینا با حضور اعضای محترم هیئت مدیره متشکل از نمایندگان محترم بنیاد مستضعفان و موسسه تحقیق و توسعه دانشمند تشکیل گردید .', 'مجمع عمومی عادی شرکت توسعه دانش بنیان سینا برای سال مالی منتهی به ۲۹ اسفند ۱۴۰۳-۰۸-۱۳ مجمع عمومی عادی شرکت توسعه دانش بنیان سینا با حضور اعضای محترم هیئت مدیره متشکل از نمایندگان محترم بنیاد مستضعفان و موسسه تحقیق و توسعه دانشمند تشکیل گردید .', 4, NULL, '2024-11-02 20:30:00', '2024-11-02 20:30:00'),
(45, NULL, 'مجمع عمومی عادی شرکت توسعه دانش بنیان سینا برای سال مالی منتهی به 30 اسفند 1403', NULL, NULL, 'مجمع-عمومی-عادی-شرکت-توسعه-دانش-بنیان-سینا-برای-سال-مالی-منتهی-به-30-اسفند-1403', 'site/posts/featured/b5tgo26ukGBvlc8YUKzTwx7w3C2UujDZn0ilmp6N.jpg', NULL, '[{\"path\":\"posts\\/gallery\\/050abvAzpeyMgOlsXMKcNFxEJ4Dwfg1KWuCJ8TB6.jpg\",\"type\":\"image\",\"name\":\"AM3A2414.jpg\"},{\"path\":\"posts\\/gallery\\/AOoKVVCXqvZHZX9QDhVDiXZzGmOIrGpCnrH59aAf.jpg\",\"type\":\"image\",\"name\":\"AM3A2421-2.jpg\"}]', 'مجمع عمومی عادی سالیانه شرکت توسعه دانش بنیان سینا با حضور اعضای هیئت مدیره متشکل از نمایندگان بنیاد مستضعفان، موسسه تحقیق و توسعه دانشمند و هلدینگ مالی و سرمایه گذاری تشکیل گردید', '<p>مجمع عمومی عادی سالیانه شرکت توسعه دانش بنیان سینا با حضور اعضای هیئت مدیره متشکل از نمایندگان محترم بنیاد مستضعفان، موسسه تحقیق و توسعه دانشمند و هلدینگ مالی وسرمایه گذاری سینا تشکیل گردید.</p><p>در این جلسه ضمن بررسی عملکرد مالی شرکت با حضور حسابرس مستقل؛ توضیحاتی در خصوص گزارش عملکرد سال مالی 1403،ارائه ترازنامه و صورت های مالی مرتبط با سینا وی سی و شرکت های تابعه ارائه شد.</p><p>در نهایت برنامه های راهبردی مورد نظر شرکت برای 2 سال آینده مورد بحث و بررسی قرار گرفت و مقرر گردید موضوع افزایش سرمایه شرکت جهت تقویت ظرفیت سرمایه گذاری خطر پذیر سینا وی سی در زیست بوم نوآوری و فناوری کشور باقید فوریت و در اسرع وقت پیگیری و دنبال شود لذا در همین خصوص تصمیمات لازم اتخاذ شد.</p>', 4, NULL, '2025-09-13 20:30:00', '2026-05-26 14:22:57'),
(46, NULL, 'مرور رویدادهای سال ۱۴۰۲ قسمت “دوم”', NULL, NULL, 'مرور-رویدادهای-سال-۱۴۰۲-قسمت-“دوم”', NULL, NULL, NULL, 'مرور رویدادهای سال ۱۴۰۲ قسمت “دوم” ۱۴۰۳-۰۱-۲۰ ویدیوی امروز به یادگار می‌ماند از رویداد پیشگامان حمل و نقل که در دوره دوم خود، رویکردی نو به “لجستیک و حمل و نقل هوشمند” عرضه داشت. در آنجا نوآوران و سرمایه‌گذاران را هم‌راستا ساختیم.', 'مرور رویدادهای سال ۱۴۰۲ قسمت “دوم” ۱۴۰۳-۰۱-۲۰ ویدیوی امروز به یادگار می‌ماند از رویداد پیشگامان حمل و نقل که در دوره دوم خود، رویکردی نو به “لجستیک و حمل و نقل هوشمند” عرضه داشت. در آنجا نوآوران و سرمایه‌گذاران را هم‌راستا ساختیم.', 4, NULL, '2024-04-07 20:30:00', '2024-04-07 20:30:00'),
