(56, NULL, 'معرفی شرکت نفت آزمایان ژرف‌اندیش', NULL, NULL, 'معرفی-شرکت-نفت-آزمایان-ژرف‌اندیش', NULL, NULL, NULL, 'معرفی شرکت نفت آزمایان ژرف‌اندیش ۱۴۰۳-۰۷-۱۶ شرکت دانش‌بنیان نفت آزمایان ژرف اندیش در سال ۱۳۹۸ تأسیس شد و از اردیبهشت ماه ۱۳۹۹ به عنوان “شرکت دانش بنیان” مورد ارزیابی و تأیید کارگروه معاونت علمی و فناوری ریاست جمهوری قرار گرفت.', 'معرفی شرکت نفت آزمایان ژرف‌اندیش ۱۴۰۳-۰۷-۱۶ شرکت دانش‌بنیان نفت آزمایان ژرف اندیش در سال ۱۳۹۸ تأسیس شد و از اردیبهشت ماه ۱۳۹۹ به عنوان “شرکت دانش بنیان” مورد ارزیابی و تأیید کارگروه معاونت علمی و فناوری ریاست جمهوری قرار گرفت.', 4, NULL, '2024-10-06 20:30:00', '2024-10-06 20:30:00');
