(59, NULL, 'نخستین جلسه بررسی طرح های حوزه فناوری مالی', NULL, NULL, 'نخستین-جلسه-بررسی-طرح-های-حوزه-فناوری-مالی', NULL, NULL, NULL, 'نخستین جلسه بررسی طرح های حوزه فناوری مالی ۱۴۰۲-۱۰-۲۶ پیرو برگزاری رویداد فراگیری و فناوری مالی، اولین جلسه بررسی طرح های این حوزه با حضور داورانی از زنجیره ارزش زنجیره مالی و سرمایه گذاری بنیاد مستضعفان مورخ ۲۶ دی ماه برگزار گردید', 'نخستین جلسه بررسی طرح های حوزه فناوری مالی ۱۴۰۲-۱۰-۲۶ پیرو برگزاری رویداد فراگیری و فناوری مالی، اولین جلسه بررسی طرح های این حوزه با حضور داورانی از زنجیره ارزش زنجیره مالی و سرمایه گذاری بنیاد مستضعفان مورخ ۲۶ دی ماه برگزار گردید', 4, NULL, '2024-01-15 20:30:00', '2024-01-15 20:30:00'),
(60, NULL, 'ظرفیت های شرکت های فعال در هوش مصنوعی، زیر ذره بین سینا وی سی', NULL, NULL, 'ظرفیت-های-شرکت-های-فعال-در-هوش-مصنوعی،-زیر-ذره-بین-سینا-وی-سی', NULL, NULL, NULL, 'ظرفیت های شرکت های فعال در هوش مصنوعی، زیر ذره بین سینا وی سی ۱۴۰۲-۱۱-۰۱ نشست شناخت ظرفیت های شرکت پارت” از شرکت های پیشرو هوش مصنوعی کشور” با حضور مدیران عامل سیناوی سی و پارت برگزار شد.', 'ظرفیت های شرکت های فعال در هوش مصنوعی، زیر ذره بین سینا وی سی ۱۴۰۲-۱۱-۰۱ نشست شناخت ظرفیت های شرکت پارت” از شرکت های پیشرو هوش مصنوعی کشور” با حضور مدیران عامل سیناوی سی و پارت برگزار شد.', 4, NULL, '2024-01-20 20:30:00', '2024-01-20 20:30:00'),
(61, NULL, 'نشست صمیمانه با مدیرعامل شرکت سهامی مادر تخصصی مدیریت ساخت و تهیه کالای آب و برق (ساتکاب)', NULL, NULL, 'نشست-صمیمانه-با-مدیرعامل-شرکت-سهامی-مادر-تخصصی-مدیریت-ساخت-و-تهیه-کالای-آب-و-برق-(ساتکاب)', NULL, NULL, NULL, 'نشست صمیمانه با مدیرعامل شرکت سهامی مادر تخصصی مدیریت ساخت و تهیه کالای آب و برق (ساتکاب) ۱۴۰۲-۰۷-۲۳ در این جلسه که با حضور مدیران عامل ساتکاب و سینا وی سی برگزار شد به معرفی شرکت های زیرمجموعه ساتکاب و ظرفیت های وسیع این شرکت پرداخته شد.', 'نشست صمیمانه با مدیرعامل شرکت سهامی مادر تخصصی مدیریت ساخت و تهیه کالای آب و برق (ساتکاب) ۱۴۰۲-۰۷-۲۳ در این جلسه که با حضور مدیران عامل ساتکاب و سینا وی سی برگزار شد به معرفی شرکت های زیرمجموعه ساتکاب و ظرفیت های وسیع این شرکت پرداخته شد.', 4, NULL, '2023-10-14 20:30:00', '2023-10-14 20:30:00'),
(62, NULL, 'نشست مشترک سینا وی سی و ستاد راهبری توسعه و فناوری های علوم شناختی معاونت علمی، فناوری و اقتصاد دانش بنیان ریاست‌جمهوری', NULL, NULL, 'نشست-مشترک-سینا-وی-سی-و-ستاد-راهبری-توسعه-و-فناوری-های-علوم-شناختی-معاونت-علمی،-فناوری-و-اقتصاد-دانش-بنیان-ریاست‌جمهوری', NULL, NULL, NULL, 'نشست مشترک سینا وی سی و ستاد راهبری توسعه و فناوری های علوم شناختی معاونت علمی، فناوری و اقتصاد دانش بنیان ریاست‌جمهوری ۱۴۰۲-۰۹-۲۹ در این جلسه که در راستای برگزاری رویداد پل سرمایه گذاری فراگیری و فناوری مالی برگزار شد نماینده سینا وی سی ضمن معرفی شر', 'نشست مشترک سینا وی سی و ستاد راهبری توسعه و فناوری های علوم شناختی معاونت علمی، فناوری و اقتصاد دانش بنیان ریاست‌جمهوری ۱۴۰۲-۰۹-۲۹ در این جلسه که در راستای برگزاری رویداد پل سرمایه گذاری فراگیری و فناوری مالی برگزار شد نماینده سینا وی سی ضمن معرفی شرکت توسعه دانش بنیان سینا به نحوه سرمایه گذاری این شرکت بر طرح های فناورانه مستعد سرمایه‌گذاری پرداخت.', 4, NULL, '2023-12-19 20:30:00', '2023-12-19 20:30:00'),
