(66, NULL, 'نشست مشترک مدیرعامل سینا وی سی و دبیرکل کانون کارگزاران بورس و اوراق بهادار ایران', NULL, NULL, 'نشست-مشترک-مدیرعامل-سینا-وی-سی-و-دبیرکل-کانون-کارگزاران-بورس-و-اوراق-بهادار-ایران', NULL, NULL, NULL, 'نشست مشترک مدیرعامل سینا وی سی و دبیرکل کانون کارگزاران بورس و اوراق بهادار ایران ۱۴۰۲-۰۸-۳۰ این جلسه در راستای همکاری و هم افزایی در راستای برگزاری رویداد پل سرمایه گذاری فراگیری و فناوری مالی برگزار شد.', 'نشست مشترک مدیرعامل سینا وی سی و دبیرکل کانون کارگزاران بورس و اوراق بهادار ایران ۱۴۰۲-۰۸-۳۰ این جلسه در راستای همکاری و هم افزایی در راستای برگزاری رویداد پل سرمایه گذاری فراگیری و فناوری مالی برگزار شد.', 4, NULL, '2023-11-20 20:30:00', '2023-11-20 20:30:00'),
(67, NULL, 'نشست مشترک مدیرعامل سینا وی سی و مدیر توسعه اکوسیستم صندوق نوآوری و شکوفایی ریاست جمهوری', NULL, NULL, 'نشست-مشترک-مدیرعامل-سینا-وی-سی-و-مدیر-توسعه-اکوسیستم-صندوق-نوآوری-و-شکوفایی-ریاست-جمهوری', NULL, NULL, NULL, 'نشست مشترک مدیرعامل سینا وی سی و مدیر توسعه اکوسیستم صندوق نوآوری و شکوفایی ریاست جمهوری ۱۴۰۲-۱۰-۰۵ این جلسه در راستای همکاری و هم افزایی هر چه بیشتر شرکت توسعه دانش بنیان سینا و صندوق نوآوری شکوفایی در راستای حمایت از طرح ها و محصولات دانش بنیان تشک', 'نشست مشترک مدیرعامل سینا وی سی و مدیر توسعه اکوسیستم صندوق نوآوری و شکوفایی ریاست جمهوری ۱۴۰۲-۱۰-۰۵ این جلسه در راستای همکاری و هم افزایی هر چه بیشتر شرکت توسعه دانش بنیان سینا و صندوق نوآوری شکوفایی در راستای حمایت از طرح ها و محصولات دانش بنیان تشکیل شد.', 4, NULL, '2023-12-25 20:30:00', '2023-12-25 20:30:00'),
(68, NULL, 'نشست پایان سال توسعه دانش بنیان سینا برگزار شد', NULL, NULL, 'نشست-پایان-سال-توسعه-دانش-بنیان-سینا-برگزار-شد', NULL, NULL, NULL, 'نشست پایان سال توسعه دانش بنیان سینا برگزار شد ۱۴۰۲-۱۲-۲۷ به گزارش روابط عمومی توسعه دانش بنیان سینا، نشست پایان سال این مجموعه با حضور مدیرعامل محترم جناب آقای یاسر خانی کشمرزی و همکاران برگزار شد.', 'نشست پایان سال توسعه دانش بنیان سینا برگزار شد ۱۴۰۲-۱۲-۲۷ به گزارش روابط عمومی توسعه دانش بنیان سینا، نشست پایان سال این مجموعه با حضور مدیرعامل محترم جناب آقای یاسر خانی کشمرزی و همکاران برگزار شد.', 4, NULL, '2024-03-16 20:30:00', '2024-03-16 20:30:00'),
(69, NULL, 'نشست پایان سال 1403 توسعه دانش بنیان سینا برگزار شد', NULL, NULL, 'نشست-پایان-سال-1403-توسعه-دانش-بنیان-سینا-برگزار-شد', 'site/posts/featured/blsAiWqgSNr93kfoCjbPWMRKUwmp8P8Q9PirY6Kt.jpg', NULL, '[]', 'به منظور قدردانی از تلاش های اعضای تیم توسعه دانش بنیان سینا، مدیرعامل محترم، جناب آقای یاسرخانی، از تمامی همکاران حاضر تقدیر و تشکر به عمل آوردند. ایشان با ابراز خرسندی از تلاش‌های بی‌وقفه مجموعه، بر اهمیت همکاری و همفکری در رسیدن به اهداف بزرگ سازمان تأکید کردند.', '<p>به منظور قدردانی از تلاش های اعضای تیم توسعه دانش بنیان سینا، مدیرعامل محترم، جناب آقای یاسرخانی، از تمامی همکاران حاضر تقدیر و تشکر به عمل آوردند. ایشان با ابراز خرسندی از تلاش‌های بی‌وقفه مجموعه، بر اهمیت همکاری و همفکری در رسیدن به اهداف بزرگ سازمان تأکید کردند.</p><p>جناب آقای یاسرخانی همچنین با اشاره به دستاوردهای سال جاری، امیدواری خود را برای سال آینده ابراز کردند و خاطرنشان کردند که انتظار می‌رود سال آینده به عنوان سالی پرکارتر و موفق‌تر برای همه همکاران سینا وی سی رقم بخورد. ایشان تأکید کردند که با اتحاد و یکدلی، می‌توانیم چالش‌ها را به فرصت‌هایی برای رشد و پیشرفت تبدیل کنیم.</p><p>این مراسم در فضایی دوستانه و صمیمی برگزار شد و با استقبال گرم همکاران روبرو گردید. امیدواریم با این روحیه و تلاش مشترک، در آینده‌ای نزدیک شاهد دستاوردهای بیشتری باشیم.</p><p>تاریخ برگزاری این مراسم در ۲۶ اسفند بود.</p>', 4, NULL, '2025-03-16 20:30:00', '2026-05-26 14:31:41'),
(70, NULL, 'نقش فنّاوری­ های مالی در نظام اقتصادی کشور بررسی می شود', NULL, NULL, 'نقش-فنّاوری­-های-مالی-در-نظام-اقتصادی-کشور-بررسی-می-شود', NULL, NULL, NULL, 'نقش فنّاوری­ های مالی در نظام اقتصادی کشور بررسی می شود ۱۴۰۲-۱۱-۰۸ نشست علمی-تخصصی در راستای رویداد پل سرمایه گذاری با عنوان” نقش فنّاوری­ های مالی در نظام اقتصادی کشور؛ چالش­ ها و توصیه­ های سیاستی ” برگزار می‌شود.', 'نقش فنّاوری­ های مالی در نظام اقتصادی کشور بررسی می شود ۱۴۰۲-۱۱-۰۸ نشست علمی-تخصصی در راستای رویداد پل سرمایه گذاری با عنوان” نقش فنّاوری­ های مالی در نظام اقتصادی کشور؛ چالش­ ها و توصیه­ های سیاستی ” برگزار می‌شود.', 4, NULL, '2024-01-27 20:30:00', '2024-01-27 20:30:00'),
(71, NULL, 'گزارش صدا و سیما از برگزاری رویداد دوشنبه استارتاپی در حوزه لجستیک و حمل و نقل هوشمند با همکاری شرکت توسعه دانش بنیان سینا', NULL, NULL, 'گزارش-صدا-و-سیما-از-برگزاری-رویداد-دوشنبه-استارتاپی-در-حوزه-لجستیک-و-حمل-و-نقل-هوشمند-با-همکاری-شرکت-توسعه-دانش-بنیان-سینا', NULL, NULL, NULL, 'گزارش صدا و سیما از برگزاری رویداد دوشنبه استارتاپی در حوزه لجستیک و حمل و نقل هوشمند با همکاری شرکت توسعه دانش بنیان سینا ۱۴۰۲-۱۰-۱۶ در پنجاهمین رویداد «دوشنبه‌های استارت‌آپی» چه گذشت؟', 'گزارش صدا و سیما از برگزاری رویداد دوشنبه استارتاپی در حوزه لجستیک و حمل و نقل هوشمند با همکاری شرکت توسعه دانش بنیان سینا ۱۴۰۲-۱۰-۱۶ در پنجاهمین رویداد «دوشنبه‌های استارت‌آپی» چه گذشت؟', 4, NULL, '2024-01-05 20:30:00', '2024-01-05 20:30:00'),
(72, NULL, 'گزیده ای از بیانات مقام معظم رهبری در خصوص تبیین شعار سال ۱۴۰۳', NULL, NULL, 'گزیده-ای-از-بیانات-مقام-معظم-رهبری-در-خصوص-تبیین-شعار-سال-۱۴۰۳', NULL, NULL, NULL, 'گزیده ای از بیانات مقام معظم رهبری در خصوص تبیین شعار سال ۱۴۰۳ ۱۴۰۳-۰۱-۰۱ بنده با مطالعه‌ی نظرات کارشناسان این مسئله به این نتیجه میرسم که یک کلید اساسی برای حلّ مشکلات اقتصادی کشور عبارت است از مسئله‌ی تولید', 'گزیده ای از بیانات مقام معظم رهبری در خصوص تبیین شعار سال ۱۴۰۳ ۱۴۰۳-۰۱-۰۱ بنده با مطالعه‌ی نظرات کارشناسان این مسئله به این نتیجه میرسم که یک کلید اساسی برای حلّ مشکلات اقتصادی کشور عبارت است از مسئله‌ی تولید', 4, NULL, '2024-03-19 20:30:00', '2024-03-19 20:30:00'),
(73, NULL, 'معرفی شرکت دانش‌بنیان ستارگان نوآور سپهر پارس', NULL, NULL, 'معرفی-شرکت-دانش‌بنیان-ستارگان-نوآور-سپهر-پارس', NULL, NULL, NULL, 'معرفی شرکت دانش‌بنیان ستارگان نوآور سپهر پارس ۱۴۰۳-۰۷-۱۶ شرکت دانش‌بنیان ستارگان نوآور سپهر پارس ، درسال 1397 توسط جمعی از فارغ‌التحصیلان دانشگاه‌های اروپا، اساتید دانشگاه‌های برتر تهران و نخبگان دانشگاهی تأسیس شده و اولین شرکت دانش‌بنیان مستقر در مر', 'معرفی شرکت دانش‌بنیان ستارگان نوآور سپهر پارس ۱۴۰۳-۰۷-۱۶ شرکت دانش‌بنیان ستارگان نوآور سپهر پارس ، درسال 1397 توسط جمعی از فارغ‌التحصیلان دانشگاه‌های اروپا، اساتید دانشگاه‌های برتر تهران و نخبگان دانشگاهی تأسیس شده و اولین شرکت دانش‌بنیان مستقر در مرکز نوآوری پژوهشگاه صنعت نفت می‌باشد', 4, NULL, '2024-10-06 20:30:00', '2024-10-06 20:30:00'),
(74, NULL, 'جذب بیش از ۶۰ میلیارد تومان اعتبار برای طرح‌های استارت‌آپی کشور', NULL, NULL, 'جذب-بیش-از-۶۰-میلیارد-تومان-اعتبار-برای-طرح‌های-استارت‌آپی-کشور', NULL, NULL, NULL, 'جذب بیش از ۶۰ میلیارد تومان اعتبار برای طرح‌های استارت‌آپی کشور ۱۴۰۲-۰۳-۲۳ دکتر مصطفی بغدادی، مدیر اکوسیستم صندوق نوآوری و شکوفایی، در چهل‌وپنجمین رویداد دوشنبه‌های استارت‌آپی: تا امروز در ۴۴ رویداد گذشته بیش از ۶۰ میلیارد تومان منابع برای تامین مالی', 'جذب بیش از ۶۰ میلیارد تومان اعتبار برای طرح‌های استارت‌آپی کشور ۱۴۰۲-۰۳-۲۳ دکتر مصطفی بغدادی، مدیر اکوسیستم صندوق نوآوری و شکوفایی، در چهل‌وپنجمین رویداد دوشنبه‌های استارت‌آپی: تا امروز در ۴۴ رویداد گذشته بیش از ۶۰ میلیارد تومان منابع برای تامین مالی طرح‌های استارت‌آپ‌ها جذب شده است.', 4, NULL, '2023-06-12 20:30:00', '2023-06-12 20:30:00'),
(75, NULL, 'فراخوان طرح برتر دانش‌بنیان در حوزه محرومیت‌زدایی', NULL, NULL, 'فراخوان-طرح-برتر-دانش‌بنیان-در-حوزه-محرومیت‌زدایی', NULL, NULL, NULL, 'فراخوان طرح برتر دانش‌بنیان در حوزه محرومیت‌زدایی ۱۴۰۲-۰۳-۲۳ اولین دوره از فراخوان طرح‌های فناورانه و دانش‌بنیان برتر در حوزه محرومیت‌زدایی از سوی معاونت علمی و فناوری و اقتصاد دانش‌بنیان ریاست جمهوری و با هدف انتخاب بهترین ایده و طرح‌های دانش‌بنیان', 'فراخوان طرح برتر دانش‌بنیان در حوزه محرومیت‌زدایی ۱۴۰۲-۰۳-۲۳ اولین دوره از فراخوان طرح‌های فناورانه و دانش‌بنیان برتر در حوزه محرومیت‌زدایی از سوی معاونت علمی و فناوری و اقتصاد دانش‌بنیان ریاست جمهوری و با هدف انتخاب بهترین ایده و طرح‌های دانش‌بنیان و راهکارهای فناورانه و نوآورانه که به دنبال رفع نیازمندی‌ها، مسائل و چالش‌های مناطق کم‌تر برخوردار کشور هستند و ظرفیت محرومیت‌زدایی از این مناطق را دارا باشند، برگزار می‌شود.', 4, NULL, '2023-06-12 20:30:00', '2023-06-12 20:30:00'),
(76, NULL, 'بازدید مدیرعامل و مدیر سرمایه گذاری سینا وی سی از شتاب دهنده رستا', NULL, NULL, 'بازدید-مدیرعامل-و-مدیر-سرمایه-گذاری-سینا-وی-سی-از-شتاب-دهنده-رستا', NULL, NULL, NULL, 'بازدید مدیرعامل و مدیر سرمایه گذاری سینا وی سی از شتاب دهنده رستا ۱۴۰۲-۰۵-۲۹ بازدید مدیرعامل سینا وی سی از شتاب دهنده رستادر این دیدار مهندس محمد علی جعفری مدیر عامل شتابدهنده رستا، به تشریح مدل فعالیت این شتابدهنده', 'بازدید مدیرعامل و مدیر سرمایه گذاری سینا وی سی از شتاب دهنده رستا ۱۴۰۲-۰۵-۲۹ بازدید مدیرعامل سینا وی سی از شتاب دهنده رستادر این دیدار مهندس محمد علی جعفری مدیر عامل شتابدهنده رستا، به تشریح مدل فعالیت این شتابدهنده', 4, NULL, '2023-08-19 20:30:00', '2023-08-19 20:30:00'),
