(112, NULL, 'بازدید مدیرعامل سینا وی سی از شهرک علمی و تحقیقاتی اصفهان', NULL, NULL, 'بازدید-مدیرعامل-سینا-وی-سی-از-شهرک-علمی-و-تحقیقاتی-اصفهان', NULL, NULL, NULL, 'بازدید مدیرعامل سینا وی سی از شهرک علمی و تحقیقاتی اصفهان ۱۴۰۲-۰۵-۲۹ مدیرعامل سینا وی سی ضمن بازدید از شهرک علمی تحقیقاتی اصفهان، با مدیر عامل ارشبکه تحقیق و توسعه اصفهان و معاون این شهرک به گفتگو پر داختند.', 'بازدید مدیرعامل سینا وی سی از شهرک علمی و تحقیقاتی اصفهان ۱۴۰۲-۰۵-۲۹ مدیرعامل سینا وی سی ضمن بازدید از شهرک علمی تحقیقاتی اصفهان، با مدیر عامل ارشبکه تحقیق و توسعه اصفهان و معاون این شهرک به گفتگو پر داختند.', 4, NULL, '2023-08-19 20:30:00', '2023-08-19 20:30:00'),
(113, NULL, 'جلسه دبیرخانه رویداد پل سرمایه گذاری فراگیری و فناوری های مالی با حضور متخصصین این حوزه برگزار شد', NULL, NULL, 'جلسه-دبیرخانه-رویداد-پل-سرمایه-گذاری-فراگیری-و-فناوری-های-مالی-با-حضور-متخصصین-این-حوزه-برگزار-شد', NULL, NULL, NULL, 'جلسه دبیرخانه رویداد پل سرمایه گذاری فراگیری و فناوری های مالی با حضور متخصصین این حوزه برگزار شد ۱۴۰۲-۰۷-۱۹ جلسه شورای همفکری رویداد پل سرمایه گذاری فراگیری و فناوری مالی با حضور مدیران بیمه سینا، سبدگردان سینا، ایرانسل، صندوق بهگزین، شرکت سرمایه گذ', 'جلسه دبیرخانه رویداد پل سرمایه گذاری فراگیری و فناوری های مالی با حضور متخصصین این حوزه برگزار شد ۱۴۰۲-۰۷-۱۹ جلسه شورای همفکری رویداد پل سرمایه گذاری فراگیری و فناوری مالی با حضور مدیران بیمه سینا، سبدگردان سینا، ایرانسل، صندوق بهگزین، شرکت سرمایه گذاری صبا، بنیاد علوی و هم چنین هلدینگ مالی و سرمایه گذاری سینا در محل شرکت توسعه دانش بنیان سینا برگزار شد.', 4, NULL, '2023-10-10 20:30:00', '2023-10-10 20:30:00'),
(114, NULL, 'جلسه دبیرخانه پل سوم سرمایه‌گذاری مابین سینا وی سی و نمایندگان شرکت‌های زنجیره ارزش مالی و سرمایه‌گذاری بنیاد مستضعفان', NULL, NULL, 'جلسه-دبیرخانه-پل-سوم-سرمایه‌گذاری-مابین-سینا-وی-سی-و-نمایندگان-شرکت‌های-زنجیره-ارزش-مالی-و-سرمایه‌گذاری-بنیاد-مستضعفان', NULL, NULL, NULL, 'جلسه دبیرخانه پل سوم سرمایه‌گذاری مابین سینا وی سی و نمایندگان شرکت‌های زنجیره ارزش مالی و سرمایه‌گذاری بنیاد مستضعفان ۱۴۰۲-۰۵-۲۲ این جلسه با حضور یاسر خانی مدیرعامل، دکتر زاهدی معاون توسعه کسب و کار هلدینگ مالی و سرمایه گذاری سینا، احسان دادور مدیر', 'جلسه دبیرخانه پل سوم سرمایه‌گذاری مابین سینا وی سی و نمایندگان شرکت‌های زنجیره ارزش مالی و سرمایه‌گذاری بنیاد مستضعفان ۱۴۰۲-۰۵-۲۲ این جلسه با حضور یاسر خانی مدیرعامل، دکتر زاهدی معاون توسعه کسب و کار هلدینگ مالی و سرمایه گذاری سینا، احسان دادور مدیر بخش استارتاپ‌های شرکت ایرانسل و…', 4, NULL, '2023-08-12 20:30:00', '2023-08-12 20:30:00'),
(115, NULL, 'نشست صمیمی با دبیرکل و اعضای هیئت مدیره انجمن کشتیرانی ایران', NULL, NULL, 'نشست-صمیمی-با-دبیرکل-و-اعضای-هیئت-مدیره-انجمن-کشتیرانی-ایران', NULL, NULL, NULL, 'نشست صمیمی با دبیرکل و اعضای هیئت مدیره انجمن کشتیرانی ایران ۱۴۰۲-۰۶-۲۸ نشست صمیمی با دبیرکل و اعضای هیئت مدیره انجمن کشتیرانی ایران', 'نشست صمیمی با دبیرکل و اعضای هیئت مدیره انجمن کشتیرانی ایران ۱۴۰۲-۰۶-۲۸ نشست صمیمی با دبیرکل و اعضای هیئت مدیره انجمن کشتیرانی ایران', 4, NULL, '2023-09-18 20:30:00', '2023-09-18 20:30:00'),
