(117, NULL, 'سرمایه گذاری جسورانه در خدمت حل فناورانه مسائل هلدینگ صنایع غذایی سینا', NULL, NULL, 'سرمایه-گذاری-جسورانه-در-خدمت-حل-فناورانه-مسائل-هلدینگ-صنایع-غذایی-سینا', NULL, NULL, NULL, 'سرمایه گذاری جسورانه در خدمت حل فناورانه مسائل هلدینگ صنایع غذایی سینا ۱۴۰۲-۰۳-۲۰ جلسه ای پیرامون همکاری مشترک میان شرکت توسعه دانش بنیان سینا و هلدینگ صنایع غذایی برگزار شد.', 'سرمایه گذاری جسورانه در خدمت حل فناورانه مسائل هلدینگ صنایع غذایی سینا ۱۴۰۲-۰۳-۲۰ جلسه ای پیرامون همکاری مشترک میان شرکت توسعه دانش بنیان سینا و هلدینگ صنایع غذایی برگزار شد.', 4, NULL, '2023-06-09 20:30:00', '2023-06-09 20:30:00'),
(118, NULL, 'جلسه هم افزایی سینا وی سی و کارایا', NULL, NULL, 'جلسه-هم-افزایی-سینا-وی-سی-و-کارایا', NULL, NULL, NULL, 'جلسه هم افزایی سینا وی سی و کارایا ۱۴۰۲-۰۵-۱۱ ظهر روز یکشنبه جلسه ای برای همکاری و هم افزایی مشترک بین گروه سرمایه گذاران نیک اندیش کارایا و توسعه دانش بنیان سینا صورت گرفت.', 'جلسه هم افزایی سینا وی سی و کارایا ۱۴۰۲-۰۵-۱۱ ظهر روز یکشنبه جلسه ای برای همکاری و هم افزایی مشترک بین گروه سرمایه گذاران نیک اندیش کارایا و توسعه دانش بنیان سینا صورت گرفت.', 4, NULL, '2023-08-01 20:30:00', '2023-08-01 20:30:00'),
(119, NULL, 'جلسه با مدیرعامل شرکت دانش بنیان فعال در حوزه معدن', NULL, NULL, 'جلسه-با-مدیرعامل-شرکت-دانش-بنیان-فعال-در-حوزه-معدن', NULL, NULL, NULL, 'جلسه با مدیرعامل شرکت دانش بنیان فعال در حوزه معدن ۱۴۰۲-۰۵-۳۱ روز دوشنبه جلسه ای با حضور مهندس خانی مدیرعامل شرکت توسعه دانش بنیان سینا و مدیرعامل محترم یکی از شرکت های پیشرو در زمینه معدنی صورت گرفت.', 'جلسه با مدیرعامل شرکت دانش بنیان فعال در حوزه معدن ۱۴۰۲-۰۵-۳۱ روز دوشنبه جلسه ای با حضور مهندس خانی مدیرعامل شرکت توسعه دانش بنیان سینا و مدیرعامل محترم یکی از شرکت های پیشرو در زمینه معدنی صورت گرفت.', 4, NULL, '2023-08-21 20:30:00', '2023-08-21 20:30:00'),
(120, NULL, 'جلسه ارائه توانمندی‌های شرکت توسعه نوآوری و فناوری تدبیر سینا', NULL, NULL, 'جلسه-ارائه-توانمندی‌های-شرکت-توسعه-نوآوری-و-فناوری-تدبیر-سینا', NULL, NULL, NULL, 'جلسه ارائه توانمندی‌های شرکت توسعه نوآوری و فناوری تدبیر سینا ۱۴۰۲-۰۵-۳۱ روز صبح دوشنبه جلسه ای با حضور مدیرعامل شرکت توسعه نوآوری و فناوری تدبیر سینا و مهندس خانی مدیرعامل شرکت توسعه دانش بنیان سینا تشکیل شد.', 'جلسه ارائه توانمندی‌های شرکت توسعه نوآوری و فناوری تدبیر سینا ۱۴۰۲-۰۵-۳۱ روز صبح دوشنبه جلسه ای با حضور مدیرعامل شرکت توسعه نوآوری و فناوری تدبیر سینا و مهندس خانی مدیرعامل شرکت توسعه دانش بنیان سینا تشکیل شد.', 4, NULL, '2023-08-21 20:30:00', '2023-08-21 20:30:00'),
(121, NULL, 'شرکت توسعه دانش‌بنیان سینا و پارک علم و فناوری دانشگاه صنعتی امیرکبیر تفاهم‌نامه امضا کردند', NULL, NULL, 'شرکت-توسعه-دانش‌بنیان-سینا-و-پارک-علم-و-فناوری-دانشگاه-صنعتی-امیرکبیر-تفاهم‌نامه-امضا-کردند', NULL, NULL, NULL, 'شرکت توسعه دانش‌بنیان سینا و پارک علم و فناوری دانشگاه صنعتی امیرکبیر تفاهم‌نامه امضا کردند ۱۴۰۲-۰۸-۱۷ شرکت‌ توسعه دانش‌بنیان سینا و پارک علم و فناوری دانشگاه صنعتی امیرکبیر ظهر امروز به منظور همکاری دوجانبه برای محرومیت‌زدایی و توسعه زیست‌بوم فناوری', 'شرکت توسعه دانش‌بنیان سینا و پارک علم و فناوری دانشگاه صنعتی امیرکبیر تفاهم‌نامه امضا کردند ۱۴۰۲-۰۸-۱۷ شرکت‌ توسعه دانش‌بنیان سینا و پارک علم و فناوری دانشگاه صنعتی امیرکبیر ظهر امروز به منظور همکاری دوجانبه برای محرومیت‌زدایی و توسعه زیست‌بوم فناوری و نوآوری کشور تفاهم‌نامه امضا کردند.', 4, NULL, '2023-11-07 20:30:00', '2023-11-07 20:30:00'),
(122, NULL, 'شرکت توسعه دانش‌بنیان سینا و مرکز مالی ایران تفاهم‌نامه همکاری امضا کردند', NULL, NULL, 'شرکت-توسعه-دانش‌بنیان-سینا-و-مرکز-مالی-ایران-تفاهم‌نامه-همکاری-امضا-کردند', NULL, NULL, NULL, 'شرکت توسعه دانش‌بنیان سینا و مرکز مالی ایران تفاهم‌نامه همکاری امضا کردند ۱۴۰۲-۰۸-۰۳ مراسم امضای تفاهم‌نامه همکاری بین شرکت‌ توسعه دانش‌بنیان سینا به عنوان بازوی سرمایه‌گذاری بنیاد مستضعفان انقلاب اسلامی و مرکز مالی ایران بعد از ظهر امروز با حضور مدی', 'شرکت توسعه دانش‌بنیان سینا و مرکز مالی ایران تفاهم‌نامه همکاری امضا کردند ۱۴۰۲-۰۸-۰۳ مراسم امضای تفاهم‌نامه همکاری بین شرکت‌ توسعه دانش‌بنیان سینا به عنوان بازوی سرمایه‌گذاری بنیاد مستضعفان انقلاب اسلامی و مرکز مالی ایران بعد از ظهر امروز با حضور مدیران عامل هر دو مجموعه در شرکت سینا وی‌سی برگزار شد.', 4, NULL, '2023-10-24 20:30:00', '2023-10-24 20:30:00'),
(123, NULL, 'بازدید مدیرعامل و مدیرسرمایه گذاری سینا وی سی از شرکت جوجه تیمره', NULL, NULL, 'بازدید-مدیرعامل-و-مدیرسرمایه-گذاری-سینا-وی-سی-از-شرکت-جوجه-تیمره', NULL, NULL, NULL, 'بازدید مدیرعامل و مدیرسرمایه گذاری سینا وی سی از شرکت جوجه تیمره ۱۴۰۲-۰۵-۲۹ در این بازدید ضمن بررسی میدانی وضعیت این شرکت ، مقرر گردید، سینا وی سی بیش از 3میلیارد تومان در این شرکت سرمایه گذاری نماید.', 'بازدید مدیرعامل و مدیرسرمایه گذاری سینا وی سی از شرکت جوجه تیمره ۱۴۰۲-۰۵-۲۹ در این بازدید ضمن بررسی میدانی وضعیت این شرکت ، مقرر گردید، سینا وی سی بیش از 3میلیارد تومان در این شرکت سرمایه گذاری نماید.', 4, NULL, '2023-08-19 20:30:00', '2023-08-19 20:30:00'),
(124, NULL, 'حضور هیئت های تجاری کشورهای خارجی در دومین رویداد پل سرمایه گذاری', NULL, NULL, 'حضور-هیئت-های-تجاری-کشورهای-خارجی-در-دومین-رویداد-پل-سرمایه-گذاری', NULL, NULL, NULL, 'حضور هیئت های تجاری کشورهای خارجی در دومین رویداد پل سرمایه گذاری ۱۴۰۲-۰۷-۰۹ در حاشیه برگزاری رویداد پل سرمایه گذاری لجستیک و حمل و نقل که به همت شرکت توسعه دانش بنیان سینا (SinaVC) در محل خانه نوآوری و فناوری ایران(IHIT) برگزار شد.', 'حضور هیئت های تجاری کشورهای خارجی در دومین رویداد پل سرمایه گذاری ۱۴۰۲-۰۷-۰۹ در حاشیه برگزاری رویداد پل سرمایه گذاری لجستیک و حمل و نقل که به همت شرکت توسعه دانش بنیان سینا (SinaVC) در محل خانه نوآوری و فناوری ایران(IHIT) برگزار شد.', 4, NULL, '2023-09-30 20:30:00', '2023-09-30 20:30:00');
