(125, NULL, 'بررسی مشکلات و موانع ترانزیت در ایران با حضور جناب آقای مهندس فرامرزیان', NULL, NULL, 'بررسی-مشکلات-و-موانع-ترانزیت-در-ایران-با-حضور-جناب-آقای-مهندس-فرامرزیان', NULL, NULL, NULL, 'بررسی مشکلات و موانع ترانزیت در ایران با حضور جناب آقای مهندس فرامرزیان ۱۴۰۲-۰۵-۰۲ بررسی مشکلات و موانع ترانزیت در ایران با حضور جناب آقای مهندس فرامرزیان دبیر حمل و نقل بین المللی و کارنه تیر اتاق ایران.', 'بررسی مشکلات و موانع ترانزیت در ایران با حضور جناب آقای مهندس فرامرزیان ۱۴۰۲-۰۵-۰۲ بررسی مشکلات و موانع ترانزیت در ایران با حضور جناب آقای مهندس فرامرزیان دبیر حمل و نقل بین المللی و کارنه تیر اتاق ایران.', 4, NULL, '2023-07-23 20:30:00', '2023-07-23 20:30:00'),
(126, NULL, 'حضور مدیران شرکت های حمل و نقل ریلی بنیاد مستضعفان در محل شرکت توسعه دانش بنیان سینا', NULL, NULL, 'حضور-مدیران-شرکت-های-حمل-و-نقل-ریلی-بنیاد-مستضعفان-در-محل-شرکت-توسعه-دانش-بنیان-سینا', NULL, NULL, NULL, 'حضور مدیران شرکت های حمل و نقل ریلی بنیاد مستضعفان در محل شرکت توسعه دانش بنیان سینا ۱۴۰۲-۰۵-۲۲ این جلسه با حضور مدیرعامل سینا وی سی، مدیرعامل سینا ریل پارس و هم چنین معاون برنامه ریزی و توسعه کسب و کار شرکت بن ریل برگزار گردید و نیاز های فناورانه حم', 'حضور مدیران شرکت های حمل و نقل ریلی بنیاد مستضعفان در محل شرکت توسعه دانش بنیان سینا ۱۴۰۲-۰۵-۲۲ این جلسه با حضور مدیرعامل سینا وی سی، مدیرعامل سینا ریل پارس و هم چنین معاون برنامه ریزی و توسعه کسب و کار شرکت بن ریل برگزار گردید و نیاز های فناورانه حمل و نقل ریلی در راستای بهبود عملکرد این صنعت مورد بحث و تبادل نظر قرار گرفت.', 4, NULL, '2023-08-12 20:30:00', '2023-08-12 20:30:00'),
(127, NULL, 'جلسه هم اندیشی پیرامون پل دوم سرمایه گذاری با حضور رئیس هیئت مدیره فدراسیون حمل و نقل ایران', NULL, NULL, 'جلسه-هم-اندیشی-پیرامون-پل-دوم-سرمایه-گذاری-با-حضور-رئیس-هیئت-مدیره-فدراسیون-حمل-و-نقل-ایران', NULL, NULL, NULL, 'جلسه هم اندیشی پیرامون پل دوم سرمایه گذاری با حضور رئیس هیئت مدیره فدراسیون حمل و نقل ایران ۱۴۰۲-۰۵-۰۷ در شروع این جلسه یاسر خانی مدیر عامل شرکت توسعه دانش بنیان سینا ضمن معرفی زیر ساخت های لجستیک و حمل و نقل بنیاد مستضعفان انقلاب اسلامی از برگزاری د', 'جلسه هم اندیشی پیرامون پل دوم سرمایه گذاری با حضور رئیس هیئت مدیره فدراسیون حمل و نقل ایران ۱۴۰۲-۰۵-۰۷ در شروع این جلسه یاسر خانی مدیر عامل شرکت توسعه دانش بنیان سینا ضمن معرفی زیر ساخت های لجستیک و حمل و نقل بنیاد مستضعفان انقلاب اسلامی از برگزاری دومین رویداد از سلسله رویداد های پل سرمایه گذاری خبر داد.', 4, NULL, '2023-07-28 20:30:00', '2023-07-28 20:30:00'),
(128, NULL, 'بررسی چالش های حمل و نقل ریلی', NULL, NULL, 'بررسی-چالش-های-حمل-و-نقل-ریلی', NULL, NULL, NULL, 'بررسی چالش های حمل و نقل ریلی ۱۴۰۲-۰۵-۰۱ این جلسه با حضور جناب آقای دکتر سبحان نظری دبیر انجمن صنفی حمل و نقل ریلی ایران در محل شرکت توسعه دانش بنیان سینا برگزار گردید. در این دیدار چالش های حمل و نقل ریلی مورد بررسی قرار گرفت.', 'بررسی چالش های حمل و نقل ریلی ۱۴۰۲-۰۵-۰۱ این جلسه با حضور جناب آقای دکتر سبحان نظری دبیر انجمن صنفی حمل و نقل ریلی ایران در محل شرکت توسعه دانش بنیان سینا برگزار گردید. در این دیدار چالش های حمل و نقل ریلی مورد بررسی قرار گرفت.', 4, NULL, '2023-07-22 20:30:00', '2023-07-22 20:30:00'),
(129, NULL, 'نشست هم اندیشی پل سرمایه گذاری دوم با حضور رئیس اندیشکده حمل و نقل ایران', NULL, NULL, 'نشست-هم-اندیشی-پل-سرمایه-گذاری-دوم-با-حضور-رئیس-اندیشکده-حمل-و-نقل-ایران', NULL, NULL, NULL, 'نشست هم اندیشی پل سرمایه گذاری دوم با حضور رئیس اندیشکده حمل و نقل ایران ۱۴۰۲-۰۵-۰۷ بررسی نقش بنیاد مستضعفان انقلاب اسلامی در کریدور شمال به جنوب با حضور جناب آقای مهندس علی ضیایی رئیس اندیشکده حمل و نقل ایران.', 'نشست هم اندیشی پل سرمایه گذاری دوم با حضور رئیس اندیشکده حمل و نقل ایران ۱۴۰۲-۰۵-۰۷ بررسی نقش بنیاد مستضعفان انقلاب اسلامی در کریدور شمال به جنوب با حضور جناب آقای مهندس علی ضیایی رئیس اندیشکده حمل و نقل ایران.', 4, NULL, '2023-07-28 20:30:00', '2023-07-28 20:30:00'),
(130, NULL, 'رونمایی از تمبر پل سرمایه گذاری', NULL, NULL, 'رونمایی-از-تمبر-پل-سرمایه-گذاری', NULL, NULL, NULL, 'رونمایی از تمبر پل سرمایه گذاری ۱۴۰۲-۰۷-۰۹ در حاشیه رویداد پل سرمایه گذاری دوم، با موضوع حمل و نقل و لجستیک، به منظور تجلیل از فعالیت های شرکت های دانش بنیان، از این تمبر رو نمایی شد.', 'رونمایی از تمبر پل سرمایه گذاری ۱۴۰۲-۰۷-۰۹ در حاشیه رویداد پل سرمایه گذاری دوم، با موضوع حمل و نقل و لجستیک، به منظور تجلیل از فعالیت های شرکت های دانش بنیان، از این تمبر رو نمایی شد.', 4, NULL, '2023-09-30 20:30:00', '2023-09-30 20:30:00'),
(131, NULL, 'دیدار صمیمانه با رئیس هیئت مدیره انجمن وی سی ایران', NULL, NULL, 'دیدار-صمیمانه-با-رئیس-هیئت-مدیره-انجمن-وی-سی-ایران', NULL, NULL, NULL, 'دیدار صمیمانه با رئیس هیئت مدیره انجمن وی سی ایران ۱۴۰۲-۰۴-۱۳ دیدار صمیمانه با رئیس هیئت مدیره انجمن وی سی ایران', 'دیدار صمیمانه با رئیس هیئت مدیره انجمن وی سی ایران ۱۴۰۲-۰۴-۱۳ دیدار صمیمانه با رئیس هیئت مدیره انجمن وی سی ایران', 4, NULL, '2023-07-03 20:30:00', '2023-07-03 20:30:00'),
(132, NULL, 'انجمن سرمایه گذاری خطر پذیر', NULL, NULL, 'انجمن-سرمایه-گذاری-خطر-پذیر', NULL, NULL, NULL, 'انجمن سرمایه گذاری خطر پذیر ۱۴۰۲-۰۳-۲۰ عضویت دومین سال متوالی سیناوی سی در انجمن ویسی انجمن سرمایه گذاری خطرپذیر ایران در حال حاضر بیش از ۵۰ عضو فعال متشکل از صندوق های پژوهش فناوری شرکت های سرمایه گذاری خطرپذیر صندوق های جسورانه و شتابدهنده ها و فرش', 'انجمن سرمایه گذاری خطر پذیر ۱۴۰۲-۰۳-۲۰ عضویت دومین سال متوالی سیناوی سی در انجمن ویسی انجمن سرمایه گذاری خطرپذیر ایران در حال حاضر بیش از ۵۰ عضو فعال متشکل از صندوق های پژوهش فناوری شرکت های سرمایه گذاری خطرپذیر صندوق های جسورانه و شتابدهنده ها و فرشتگان کسب و کار می باشد.', 4, NULL, '2023-06-09 20:30:00', '2023-06-09 20:30:00'),
(133, NULL, '«سینا» به انجمن سرمایه گذاری خطر پذیر کشور پیوست', NULL, NULL, '«سینا»-به-انجمن-سرمایه-گذاری-خطر-پذیر-کشور-پیوست', NULL, NULL, NULL, '«سینا» به انجمن سرمایه گذاری خطر پذیر کشور پیوست ۱۴۰۲-۰۳-۲۰ صندوق توسعه دانش‌بنیان سینا به سایر اعضای انجمن سرمایه گذاری خطرپذیر کشور ملحق گردید.', '«سینا» به انجمن سرمایه گذاری خطر پذیر کشور پیوست ۱۴۰۲-۰۳-۲۰ صندوق توسعه دانش‌بنیان سینا به سایر اعضای انجمن سرمایه گذاری خطرپذیر کشور ملحق گردید.', 4, NULL, '2023-06-09 20:30:00', '2023-06-09 20:30:00'),
(134, NULL, 'سرمایه گذاری خطرپذیر چیست و صندوق‌های سرمایه گذاری خطرپذیر چگونه کار می‌کنند؟', NULL, NULL, 'سرمایه-گذاری-خطرپذیر-چیست-و-صندوق‌های-سرمایه-گذاری-خطرپذیر-چگونه-کار-می‌کنند؟', NULL, NULL, NULL, 'سرمایه گذاری خطرپذیر چیست و صندوق‌های سرمایه گذاری خطرپذیر چگونه کار می‌کنند؟ ۱۴۰۲-۰۳-۲۰ سرمایه گذاری جسورانه یا خطر‎پذیر، به سرمایه گذاری بر روی شرکت‎های استارتاپی یا شرکت‎های نوپای مقیاس پذیر گفته می‎شود.', 'سرمایه گذاری خطرپذیر چیست و صندوق‌های سرمایه گذاری خطرپذیر چگونه کار می‌کنند؟ ۱۴۰۲-۰۳-۲۰ سرمایه گذاری جسورانه یا خطر‎پذیر، به سرمایه گذاری بر روی شرکت‎های استارتاپی یا شرکت‎های نوپای مقیاس پذیر گفته می‎شود.', 4, NULL, '2023-06-09 20:30:00', '2023-06-09 20:30:00'),
(135, NULL, 'جلسه اساتید کارگاه آموزشی حمل و نقل با مدیرعامل شرکت توسعه دانش بنیان سینا', NULL, NULL, 'جلسه-اساتید-کارگاه-آموزشی-حمل-و-نقل-با-مدیرعامل-شرکت-توسعه-دانش-بنیان-سینا', NULL, NULL, NULL, 'جلسه اساتید کارگاه آموزشی حمل و نقل با مدیرعامل شرکت توسعه دانش بنیان سینا ۱۴۰۲-۰۹-۰۸ روز سه شنبه مورخ 7 آذر 1402 جلسه ای با حضور اساتید کارگاه آموزشی آشنایی با حمل و نقل با رویکرد سرمایه گذاری جسورانه و مدیرعامل شرکت توسعه دانش بنیان سینا در محل شرک', 'جلسه اساتید کارگاه آموزشی حمل و نقل با مدیرعامل شرکت توسعه دانش بنیان سینا ۱۴۰۲-۰۹-۰۸ روز سه شنبه مورخ 7 آذر 1402 جلسه ای با حضور اساتید کارگاه آموزشی آشنایی با حمل و نقل با رویکرد سرمایه گذاری جسورانه و مدیرعامل شرکت توسعه دانش بنیان سینا در محل شرکت توسعه دانش بنیان سینا برگزار شد.', 4, NULL, '2023-11-28 20:30:00', '2023-11-28 20:30:00');

-- --------------------------------------------------------

--
-- Table structure for table `projects`
--

CREATE TABLE `projects` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `title` varchar(255) DEFAULT NULL COMMENT 'عنوان طرح',
  `cover` text DEFAULT NULL,
  `company_name` varchar(255) DEFAULT NULL COMMENT 'نام شرکت',
  `legal_type` varchar(191) DEFAULT NULL COMMENT 'نوع شخصیت حقوقی (مانند سهامی خاص، مسئولیت محدود و...)',
  `economic_code` varchar(191) DEFAULT NULL COMMENT 'کد اقتصادی شرکت',
  `registration_date` varchar(191) DEFAULT NULL COMMENT 'تاریخ ثبت شرکت',
  `registration_number` varchar(191) DEFAULT NULL COMMENT 'شماره ثبت شرکت',
  `user_id` bigint(20) DEFAULT NULL COMMENT 'کاربر',
  `CEO` varchar(255) DEFAULT NULL COMMENT 'نام کامل مدیرعامل',
  `ceo_national_code` varchar(191) DEFAULT NULL COMMENT 'کد ملی مدیرعامل',
  `website` varchar(191) DEFAULT NULL COMMENT 'وب‌سایت شرکت',
  `tel` varchar(20) DEFAULT NULL COMMENT 'تلفن شرکت',
  `email` varchar(255) DEFAULT NULL COMMENT 'ادرس ایمیل شرکت',
  `address` text DEFAULT NULL COMMENT 'آدرس موقعیت شرکت',
  `postal_code` varchar(191) DEFAULT NULL COMMENT 'کد پستی شرکت',
  `city` varchar(191) DEFAULT NULL COMMENT 'شهر محل استقرار شرکت',
  `state` varchar(191) DEFAULT NULL COMMENT 'استان محل استقرار شرکت',
  `lat` text DEFAULT NULL COMMENT 'طول جغرافیایی',
  `lng` text DEFAULT NULL COMMENT 'عرض جغرافیایی',
  `progress_percentage` int(11) DEFAULT NULL,
  `start_date` date DEFAULT NULL COMMENT 'تاریخ شروع قرارداد',
  `amount_request_accept` bigint(20) DEFAULT NULL COMMENT 'کل مبلغ توافق شده',
  `amount_commitment_first_stage` bigint(20) DEFAULT NULL COMMENT 'مبلغ مرحله اول',
  `amount_commitment_second_stage` bigint(20) DEFAULT NULL COMMENT 'مبلغ مرحله دوم',
  `amount_commitment_third_stage` bigint(20) DEFAULT NULL COMMENT 'مبلغ مرحله سوم',
  `amount_commitment_fourth_stage` bigint(20) DEFAULT NULL COMMENT 'مبلغ مرحله چهارم',
  `amount_commitment_fifth_stage` bigint(20) DEFAULT NULL COMMENT 'مبلغ مرحله پنجم',
  `percentageshare` varchar(10) DEFAULT '0',
  `logo` varchar(191) DEFAULT NULL COMMENT 'تصویر لوگو شرکت',
  `invest_step` tinyint(4) NOT NULL DEFAULT 1 COMMENT 'مرحله فرایند سرمایه گذاری',
  `reject_step` tinyint(4) DEFAULT NULL,
  `description` text DEFAULT NULL COMMENT 'توضیحات طرح',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `national_id` varchar(255) DEFAULT NULL COMMENT 'شماره ملی شرکت',
  `is_rejected` tinyint(1) DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

