(108, 'افق مبین', 'site/images/project/', 'صنعت پژوهان افق مبین', 'سهامی خاص', NULL, NULL, '554140', 28, 'مهدیه بختیاری', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '0000-00-00', 0, 0, 0, 0, 0, 0, '0', 'uploads/108/images/6875dc7a4984f.png', 20, NULL, 'کاهش میزان سم آفلاتوکسین در ذرت با استفاده از فناوری پلاسمای سرد', NULL, '2025-08-09 10:29:58', '108', 0),
(109, 'سجایا نگار', 'site/images/project/', 'سامانه های یکپارچه اندیشه نگار', 'سهامی خاص', NULL, NULL, '560521', 27, 'هانی وحدانی', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '0000-00-00', 1283894000, 1283894000, 0, 0, 0, 0, '0', 'uploads/109/images/6875d521bf42d.png', 20, NULL, 'شرکت سامانه های یکپارچه اندیشه نگار توانسته با تکیه بر دانش و فناوری روز و بهره‌مندی از سرمایه انسانی خبره، چرخه کامل توسعه محصول را با موفقیت پیاده‌سازی نماید و به ارائه راهکارها و خدمات ابری، منطبق بر نیازمندی‌های اختصاصی مشتریان بپردازد.', NULL, '2026-01-05 09:42:54', '109', 0),
(112, 'بازی سرگرمی هوشمند', 'site/images/project/', 'توسعه سرگرمی هوشمند پویا', NULL, NULL, NULL, '543790', 26, 'عبدالرضا اکرمی', '0073395366', NULL, NULL, NULL, NULL, '1911933993', NULL, NULL, NULL, NULL, 0, '1398-01-10', 5000000000, 500000000, 0, 0, 0, 0, '0', 'uploads/112/images/6875d266b5e70.png', 20, NULL, 'شرکت توسعه سرگرمی هوشمند پویا جهت توسعه بازی های موبایلی در سال 97 تاسیس گردید و در حال حاضر مشغول کار بر روی یک بازی آنلاین نوبتی (Turn Base) کارتی می باشند.', NULL, '2026-01-05 11:29:10', '112', 0),
(113, 'توانیتو', 'site/images/project/', 'توان سفیر پارسیان', NULL, NULL, NULL, '545749', 25, 'وحید رجبلو', '0310356229', NULL, NULL, NULL, NULL, '1459947311', NULL, NULL, NULL, NULL, 0, '1398-05-27', 8000000000, 350000000, 450000000, 0, 0, 0, '25', 'uploads/113/images/6874bc1d7d29b.png', 19, NULL, 'شرکت توان سفیر پارسیان با برند توانیتو در حوزه خدمات رسانی آنلاین در حوزه سلامت و عمومی به افراد دارای معلولیت، سالمندان وتوانیابان خدمت ارائه می نماید.\nدر توانیتو تلاش میشود تا افراد با نیازهای خاص، از کلیه خدمات درمانی و عمومی متناسب با شرایط جسمی خود بهره‌مند شوند. \nتوانیتو کسب‌وکاری ایرانی است که می‌کوشد با استفاده از فناوری روز، علوم کامپیوتر، اینترنت و دستگاه‌های هوشمند زندگی را برای شهروندان دارای معلولیت، سالمندان، بیماران و سایر اقشار جامعه راحت‌تر نماید.', NULL, '2026-01-05 11:01:14', '113', 0),
(114, 'ستارگان', 'site/images/project/6874b320b3225.jpg', 'ستارگان نوآور سپهر پارس', 'سهامی خاص', '14007982993', NULL, '534684', 21, 'علی پور خلیل', '2002773955', 'https://sepehr-pars.ir', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '1399-01-10', 21900000000, 5475000000, 4380000000, 4380000000, 5475000000, 5475000000, '40', 'uploads/114/images/6874b320b3225.jpg', 20, NULL, 'شرکت ستارگان نوآور سپهر پارس در سال 1397 تأسیس شده و با توسعه ماژول های غشایی پوشش دهی شده در حوزه فرآیند های جداسازی به عنوان یکی از شرکت های دانش بنیان فعال در عرصه تصفیه آب و پساب در حال فعالیت می باشد. همچنین این شرکت به عنوان اولین شرکت دانش بنیان موفق به استقرار در مرکز نوآوری پژوهشگاه صنعت نفت شده است. از جمله دیگر خدمات قابل ارائه شرکت میتوان به موارد ذیل اشاره نمود:\r\n1.تولید دستگاه های نوین غشایی برای گازدهی به آب به منظور تأمین اکسیژن مورد نیاز در مزارع پرورش ماهی و میگو\r\n2. بهبود ضریب تبدیل غذایی، کاهش دوره رشد ماهی، کاهش تلفات آبزیان، افزایش ظرفیت تولید و ...\r\n3.  امکان تزریق اکسیژن به آب و رساندن غلظت اکسیژن به %100 تا %300 با استفاده از ماژول های غشایی کامپوزیتی و با فناوری پتنت شده بین المللی', NULL, '2025-07-21 05:54:16', '114', 0),
(115, 'مپ', 'site/images/project/6874b2ca03702.jpg', 'شیوه نرم افزار گستر آسیا', 'سهامی خاص', '411558785873', NULL, '497810', 23, 'امین علی اکبریان', '0064664325', 'https://map.ir', NULL, NULL, NULL, '1531735614', NULL, NULL, NULL, NULL, 0, '1397-02-20', 18000000000, 600000000, 800000000, 400000000, 0, 0, '30', 'uploads/115/images/6874b2ca03702.jpg', 19, NULL, 'شرکت شیوه نرم افزار گستر آسیا با برند مپ، دارای کاربردهایی از جمله سرویس نمایش نقشه مپ برای اهداف مختلفی مانند نمایش محل های خاصی روی نقشه به کاربر، دریافت موقعیت کاربر و همچنین به عنوان پیش زمینه ای برای استفاده از سرویس های نقشه محور مانند کروکی و مسیریابی استفاده میشود.', NULL, '2026-01-05 11:28:06', '115', 0),
(116, 'نویسش', 'site/images/project/6874adc115734.jpg', 'داده پژوهان مانا', 'سهامی خاص', NULL, NULL, '545339', 24, 'میلاد اسلامی زاد', '4420037008', 'https://nevisesh.com', NULL, NULL, NULL, '1591639675', NULL, NULL, NULL, NULL, 0, '1398-08-07', 8000000000, 400000000, 400000000, 0, 0, 0, '28', 'uploads/116/images/6874adc115734.jpg', 19, NULL, 'شرکت داده پژوهان مانا با عنوان طرح نویسش بـا همکاری صـدهـا مـتخصص تـولید مـحتوا در حـوزه هـای گـونـاگـون، مـحتوایی حـرفـه ای و اسـتانـدارد را مـتناسـب بـا نیاز کارفـرمـا تولید میکند.', NULL, '2025-12-27 11:37:24', '116', 0),
(117, 'گره بافت', 'site/images/project/687222dbcc11e.jpg', 'داده کاوی سدید سپاهان', NULL, NULL, NULL, NULL, 18, 'محمد سعید احمدی', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '1402-11-15', 39000000000, 15000000000, 12000000000, 12000000000, 0, 0, '30', 'uploads/117/images/687222dbcc11e.jpg', 18, NULL, 'شرکت داده کاوی سدید سپاهان باعنوان طرح گره بافت، یکی از فعالان حوزه فرش دستبافت و سنتی می باشد که هنر را با صنعت در آمیخته است تاتوانسته فرش های ارزشمندی را تولید نماید و در پلتفرم یا سکوی بر خط ارائه نماید.', NULL, '2025-12-27 16:27:08', '117', 0),
(118, 'سورتر', 'site/images/project/68749310bfb23.jpg', 'سینا فن آوران کوثر', 'سهامی خاص', NULL, NULL, '627304', 17, 'حسین توحیدی', NULL, 'info@sinafanavar.com', NULL, NULL, NULL, '1473718371', NULL, NULL, NULL, NULL, 0, '1402-11-09', 49900000000, 32400000000, 1375000000, NULL, 0, 0, '38', 'uploads/118/images/68749310bfb23.jpg', 18, NULL, 'شرکت سینا فناوران کوثر درسال 1402 تاسیس گردیده است. این شرکت دارای ماشین های سورتینگ پردازش تصویر و لیزری می باشد که با کارکرد هوش مصنوعی قادر است تمام ویژگی های ظاهری محصولات کشاورزی را با سرعت و دقتی فراز از چشم انسان تشخیص داده و در نتیجه از این طریق طبقه بندی محصولات  بر اساس اندازه گیری شکل، تشخیص رنگ، نقص ظاهری، تشخیص پارامترهای بیولوژیکی، جداسازی مواد خارجی همچون پوست وسنگ در این سامانه ها در کسری از ثانیه امکان پذیر می باشد.', NULL, '2025-12-27 16:27:35', '118', 0),
(119, 'بارنت', 'site/images/project/68721e3e8ff9f.jpg', 'باربان سیر پارسیان', 'سهامی خاص', '14009292498', NULL, '65120', 19, 'جناب آقای نوید نیلی', '1272004856', 'https://baarnet.com', NULL, NULL, NULL, '8193654681', NULL, NULL, NULL, NULL, 0, '1403-02-02', 50000000000, 30000000000, 1000000000, 1000000000, 0, 0, '12', 'uploads/119/images/68721e3e8ff9f.jpg', 18, NULL, 'شرکت باربان سیر پارسیان با عنوان طرح بارنت، یک سامانه تخصصی آنلاین می باشد که در زمینه حمل بار درون وبرون شهری فعالیت می نماید.\r\nاین کسب وکار با هدف ایجاد پلتفرم جامع هوشمند و کاربردی در زمینه حمل ونقل بار شکل گرفته و به نحوی طراحی شده است که ضمن تلاش در جهت تبدیل سیستم حمل ونقل سنتی به آنلاین، چالش های موجود آن را برطرف میکند.\r\nاز جمله مزایای رقابتی بارنت را میتوان به شرح ذیل عنوان کرد:\r\n1. بیمه آنلاین بار\r\n2. همکاری اعتباری با سازمان ها\r\n3. وجود رانندگان قراردادی با دریافت تضامین\r\n4. تنوع خودروی حمل بار', NULL, '2025-12-27 16:27:58', '119', 0),
(120, 'تیمره', 'site/images/project/6874a1185c7ce.jpg', 'فرتاک جوجه تیمره', 'مسئولیت محدود', '411649118463', NULL, '15523', 16, 'امید افسریان', '0559040997', '-', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '1402-08-15', 35000000000, 500000000, 2000000000, 1000000000, 0, 0, '30', 'uploads/120/images/6874a1185c7ce.jpg', 18, NULL, 'شرکت فرتاک جوجه تیمره در ابتدا فعالیت خود را با تولید جوجه گوشتی یکروزه مقاوم در برابر سرما آغاز و در فاز دوم اقدام به پرورش مرغ بومی آرین کرد. در حال حاضر نیز با هدف تکمیل زنجیر ارزش دام وطیور، برنامه تولید انبوه خوراک دام سبک واستاندارد بر پایه پسماند بهداشتی صنابع غذایی مطابق با نیاز دام را دست دارد.\r\nخوراک دام تیمره از پسماندهای صنابع غذایی نظیر تفاله کارخانجات مرکبات، سبوس کنجد و در راس آنها بلوط می باشد و منجر به حذف  کنجاله سویا، جو و ذرت شده و بهبود آنالیز لاشه را به همراه دارد.', NULL, '2025-12-27 16:28:17', '120', 0),
(121, 'نفت آزمایان', 'site/images/project/68749bb789b21.jpg', 'نفت آزمایان ژرف اندیش', 'سهامی خاص', NULL, NULL, '551708', 22, 'احمد غلامی', '0451317041', 'http://naftazco.ir', NULL, NULL, NULL, '1519613525', NULL, NULL, NULL, NULL, 40, '1399-01-10', 50000000000, 1500000000, 1500000000, 1250000000, 750000000, 0, '0', 'uploads/121/images/68749bb789b21.jpg', 18, NULL, 'شرکت نفت آزمایان ژرف اندیش به واسطه طراحی وساخت سیستم مانیتورینگ پارامترهای حفاری، یونیت نمونه گیری از حفاری وسیستم تعمیرات پیشگیرانه که هر سه محصول دارای گواهی ثبت اختراع بوده و در حال حاضر نیز به صورت عملیاتی در حال کار می باشند، از کارنامه موفق برخوددار می باشند و صرفه جویی ارزی قابل توجهی را به همراه داشته است.', NULL, '2025-12-27 12:23:18', '121', 0),
(122, 'سماکنترل', 'site/images/project/687c6c8e4cc66.jpg', 'رایان آروین الگوریتم', 'سهامی خاص', '14006526891', NULL, '213165465465', 15, 'خانم کفاش', '0944725783', 'https://samacontrol.com', NULL, NULL, NULL, '1346955496', NULL, NULL, NULL, NULL, 0, '1402-11-15', 42000000000, 25000000000, 15000000000, 10000000000, 0, 0, '20.97', 'uploads/122/images/687c6c8e4cc66.jpg', 18, NULL, 'شرکت رایان آروین الگوریتم با عنوان محصولی به نام سما کنترل در سال 1395 تاسیس گردیده است. هدف این شرکت توانمند سازی کشاورزان می باشد و محصول تولید شده دارای ویژگی های ذیل می باشد:\r\n1. محاسبات نیاز دقیق آبیاری\r\n2. محاسبات و تصمیم گیری میتنی بر کم آبیاری تنظیم شده\r\n3. پیش بینی شرایط اقلیمی بر اساس داده های هواشناسی', NULL, '2025-12-27 16:30:16', '122', 0),
