--
-- Table structure for table `project_steps`
--

CREATE TABLE `project_steps` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `project_id` bigint(20) UNSIGNED DEFAULT NULL COMMENT 'طرح ',
  `title` varchar(255) DEFAULT NULL COMMENT 'عنوان',
  `step_number` int(11) DEFAULT NULL COMMENT 'شماره گام',
  `description` text DEFAULT NULL COMMENT 'توضیحات',
  `status` varchar(255) DEFAULT NULL COMMENT 'وضعیت',
  `active` tinyint(4) NOT NULL DEFAULT 1,
  `user_id` bigint(20) UNSIGNED DEFAULT NULL COMMENT 'کارشناس ',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

