(12, 120, 'بررسی اولیه', 2, 'سرمایه پذیر گرامی با توجه به تایید فایل پیچ دک ارسالی شما در مرحله قبل، جلسه ارائه طرح تاریخ 1402/07/20 ساعت 10 برگزار میگردد، لذا حضور تیم شما در این جلسه الزامی می باشد.', 'approved', 1, 2, '2025-09-28 08:51:51', '2025-09-28 08:51:51'),
(13, 120, 'غربالگری', 3, 'با توجه به جلسه برگزار شده ارائه طرح، به اطلاع میرساند طرح شرکت شما در این مرحله مورد تایید میباشد. \r\nجهت ارائه حضوری مباحث مربوط به طرح با حضور مدیر سرمایه گذاری شرکت توسعه دانش بنیان سینا، مطابق اطلاعات ارسالی(شامل تاریخ، ساعت و محل جلسه) در تقویم کاری خود اقدام بفرمایید', 'approved', 1, 2, '2025-09-28 10:21:50', '2025-09-28 10:21:50'),
(14, 120, 'ارزیابی اولیه', 4, 'سرمایه پذیر محترم با توجه به جلسات پیشین، به اطلاع میرساند طرح فناورانه شرکت شما در مرحله ارزیابی اولیه، موفق به کسب امتیاز مورد تایید گردیده است، لذا در انتظار پیام بعدی ما باشید.', 'approved', 1, 2, '2025-09-28 11:48:13', '2025-09-28 11:48:13'),
(15, 120, 'کمیته ریسک و سرمایه گذاری', 5, NULL, 'approved', 1, 2, '2025-09-28 11:52:27', '2025-09-28 11:52:27'),
(16, 122, 'ارسال فایل پیچ دک', 1, 'سرمایه پذیر محترم، فایل ارسالی مورد تایید می باشد.', 'approved', 1, 2, '2025-09-28 14:51:17', '2025-09-28 14:51:17'),
(17, 122, 'بررسی اولیه', 2, 'سرمایه پذیر با توجه فایل ارسالی پیچ دک و تایید آن، جهت ارائه آنلاین طرح در تاریخ 1402/06/10 ساعت 10 مطابق اطلاعات ارسالی در تقویم کاری اقدام نمایید.', 'approved', 1, 2, '2025-09-28 14:56:48', '2025-09-28 14:56:48'),
