(46, 120, 'ارزیابی موشکافانه', 6, 'با سلام\r\nطرح شما در مرحله ارزیابی موشکافانه مورد تایید می باشد. جهت تایید طرح توسط هیئت مدیره سینا وی سی منتظر باشید.', 'approved', 1, 2, '2025-10-13 10:32:23', '2025-10-13 10:32:23'),
