(49, 122, 'بررسی اولیه', 2, 'سرمایه پذیر گرامی طرح شما در مرحله بررسی اولیه مورد تایید می باشد. جهت ارائه آنلاین طرح در تاریخ 1402/07/12 مطابق اطلاعات ارسالی در تقویم کاری خود حضور پیدا کنید\r\nبا تشکر', 'approved', 1, 2, '2025-10-14 13:26:45', '2025-10-14 13:26:45'),
(50, 122, 'غربالگری', 3, 'سرکار خانم کفاش \r\nبا توجه به جلسات برگزار شده، طرح شما در مرحله غربالگری مورد تایید می باشد', 'approved', 1, 2, '2025-10-14 13:31:34', '2025-10-14 13:31:34'),
(51, 117, 'ارسال فایل پیچ دک', 1, 'با سلام\r\nبا توجه به فایل پیچ دک ارسالی، طرح شما در این مرحله مورد تایید می باشد', 'approved', 1, 2, '2025-10-14 13:57:16', '2025-10-14 13:57:16'),
(52, 117, 'ارسال فایل پیچ دک', 1, 'با سلام\r\nبا توجه به فایل پیچ دک ارسالی، طرح شما در این مرحله مورد تایید می باشد', 'approved', 1, 2, '2025-10-14 13:57:28', '2025-10-14 13:57:28'),
(56, 120, 'تایید هیئت مدیره وی سی', 7, 'با سلام\r\nبه اطلاع میرساند طرح شما تاییدیه هیئت مدیره سینا وی سی را دریافت نموده است. خواهشمند است جهت ورود به مرحله بعد در انتظار باشید.', 'approved', 1, 2, '2025-11-11 11:37:11', '2025-11-11 11:37:11'),
(57, 120, 'تایید موسسه دانشمند', 8, 'با سلام\r\nبه اطلاع میرساند دریافت تاییدیه هیئت مدیره موسسه دانشمند جهت سرمایه گذاری در طرح شرکت شما اخذ گردیده است. جهت ارزشگذاری شرکت، کارشناسان سینا وی سی با شما در تماس خواهند بود.', 'approved', 1, 2, '2025-11-11 11:55:53', '2025-11-11 11:55:53'),
(58, 120, 'ارزش‌ گذاری', 9, 'با توجه به ارزشگذاری انجام شده شرکت شما، به استحضار میرساند مرحله بعدی فرآیند بررسی طرح شما، ارائه طرح در کمیته ارزشگذاری می باشد. پس از ارائه طرح در کمیته، نتایج اطلاع رسانی خواهد شد.', 'approved', 1, 2, '2025-11-11 12:08:28', '2025-11-11 12:08:28'),
(59, 120, 'ارائه در کمیته ارزش‌گذاری', 10, 'با سلام و وقت بخیر\r\nطرح شما در کمیته ارزشگذاری بررسی و مبلغ مصوب ارزشگذاری شرکت 6 میلیارد تومان مصوب گردید.', 'approved', 1, 2, '2025-11-11 13:39:38', '2025-11-11 13:39:38'),
