(111, 119, 'تایید موسسه دانشمند', 8, 'با سلام و احترام\r\nبه اطلاع میرساند طرح شرکت موافقت موسسه دانشمند جهت سرمایه گذاری را دریافت نموده است.\r\nجهت هماهنگی های مربوطه برای انجام ارزشگذاری طرح در انتظار اطلاع سینا وی سی باشید.', 'approved', 1, 2, '2025-11-22 16:08:42', '2025-11-22 16:08:42'),
(112, 123, 'ارسال فایل پیچ دک', 1, 'با سلام \r\nضمن عرض تشکر بابت ارائه طرح، به اطلاع میرساند طرح شما در مرحله غربالگری مورد قبول می باشد.', 'approved', 1, 2, '2025-11-25 11:03:16', '2025-11-25 11:03:16'),
(113, 123, 'بررسی اولیه', 2, 'با سلام\r\nبا توجه به پذیرش طرح مربوطه، جهت ارائه طرح به صورت آنلاین کارشناسان سینا وی سی با شما در تماس خواهند بود.', 'approved', 1, 2, '2025-11-25 11:05:45', '2025-11-25 11:05:45'),
(114, 123, 'غربالگری', 3, 'با سلام \r\nضمن عرض تشکر بابت ارسال طرح، به اطلاع میرساند طرح شما در مرحله غربالگری مورد قبول می باشد. جهت انجام ارائه طرح به صورت حضوری، کارشناسان با شما در ارتباط خواهند بود.', 'approved', 1, 2, '2025-11-25 11:09:59', '2025-11-25 11:09:59'),
(115, 119, 'ارزش‌ گذاری', 9, 'با سلام به اطلاع میرساند ارزشگذاری طرح شرکت شما به اتمام رسیده است و پس از ارائه طرح در کمیته ارزشگذاری، مبلغ مصوب ارزش طرح خدمتتان اطلاع رسانی خواهد شد.', 'approved', 1, 2, '2025-12-02 13:59:31', '2025-12-02 13:59:31'),
(116, 119, 'ارائه در کمیته ارزش‌گذاری', 10, 'با سلام واحترام\r\nبه اطلاع میرساند با توجه به برگزاری کمیته ارزشگذاری، مبلغ مصوب ارزش شرکت شما  220میلیون ریال تعیین گردیده است. جهت عقد قرارداد سرمایه گذاری، در انتظار اطلاع کارشناسان سینا وی سی باشید', 'approved', 1, 2, '2025-12-02 14:06:31', '2025-12-02 14:06:31'),
