--
-- Table structure for table `users`
--

CREATE TABLE `users` (
  `id` bigint(20) UNSIGNED NOT NULL COMMENT 'شناسه یکتا کاربر',
  `name` varchar(255) DEFAULT NULL COMMENT 'نام کامل کاربر',
  `username` varchar(255) DEFAULT NULL COMMENT 'نام کاربری برای ورود',
  `email` varchar(255) DEFAULT NULL COMMENT 'آدرس ایمیل',
  `email_verify` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'تایید ایمیل (0=تایید نشده، 1=تایید شده)',
  `email_verified_at` timestamp NULL DEFAULT NULL COMMENT 'تاریخ و زمان تایید ایمیل',
  `level` varchar(20) NOT NULL DEFAULT 'site' COMMENT 'سطح دسترسی کاربر مانند site یا panel',
  `api_token` varchar(255) DEFAULT NULL COMMENT 'توکن API برای دسترسی از طریق کلاینت‌ها',
  `password` varchar(255) DEFAULT NULL COMMENT 'رمز عبور هش شده',
  `two_factor_secret` text DEFAULT NULL,
  `two_factor_recovery_codes` text DEFAULT NULL,
  `two_factor_confirmed_at` timestamp NULL DEFAULT NULL,
  `image` varchar(255) DEFAULT NULL COMMENT 'آدرس تصویر پروفایل',
  `phone` varchar(255) DEFAULT NULL COMMENT 'شماره تلفن همراه',
  `phone_verify` tinyint(1) DEFAULT NULL COMMENT 'وضعیت تایید شماره همراه',
  `telphone` varchar(255) DEFAULT NULL COMMENT 'شماره تلفن ثابت',
  `national_id` varchar(10) DEFAULT NULL COMMENT 'کد ملی کاربر',
  `user_job` varchar(191) DEFAULT NULL COMMENT 'عنوان شغلی کاربر',
  `marital_status` varchar(191) DEFAULT NULL COMMENT 'وضعیت تاهل کاربر',
  `role_id` bigint(20) DEFAULT NULL,
  `state_id` bigint(20) UNSIGNED DEFAULT NULL,
  `city_id` bigint(20) UNSIGNED DEFAULT NULL,
  `birthday` varchar(255) DEFAULT NULL COMMENT 'تاریخ تولد به فرمت میلادی یا شمسی',
  `gender` int(11) DEFAULT NULL COMMENT 'جنسیت (مثلاً 1=مرد، 2=زن)',
  `age` int(11) DEFAULT NULL COMMENT 'سن',
  `originality` varchar(255) DEFAULT NULL COMMENT 'اصالت یا محل تولد کاربر',
  `postalcode` varchar(20) DEFAULT NULL COMMENT 'کد پستی',
  `father_name` varchar(255) DEFAULT NULL COMMENT 'نام پدر',
  `birth_certificate` varchar(255) DEFAULT NULL COMMENT 'شماره شناسنامه',
  `job_title` varchar(255) DEFAULT NULL COMMENT 'عنوان شغلی دقیق',
  `education_id` bigint(20) DEFAULT NULL COMMENT 'مدرک تحصیلی یا مقطع تحصیلی',
  `folder_id` bigint(20) DEFAULT NULL COMMENT 'شناسه پرونده کاربر',
  `folder_validity` varchar(255) DEFAULT NULL COMMENT 'تاریخ اعتبار پرونده',
  `folder_base` bigint(20) DEFAULT NULL COMMENT 'مبنا یا ریشه پرونده',
  `place_id` bigint(20) DEFAULT NULL COMMENT 'محل صدور شناسنامه یا محل خاص دیگر',
  `address` text DEFAULT NULL COMMENT 'آدرس کامل محل سکونت',
  `social` text DEFAULT NULL COMMENT 'شبکه‌های اجتماعی به صورت JSON یا متن',
  `bio` text DEFAULT NULL COMMENT 'بیوگرافی یا توضیحات درباره کاربر',
  `status` tinyint(1) DEFAULT NULL COMMENT 'وضعیت کاربر (فعال یا غیرفعال)',
  `change_password` tinyint(4) DEFAULT NULL,
  `remember_token` varchar(100) DEFAULT NULL COMMENT 'توکن یادآوری برای ورودهای بعدی',
  `google_id` text DEFAULT NULL,
  `google_token` text DEFAULT NULL,
  `google_refresh_token` text DEFAULT NULL,
  `google_expires_in` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

