-- --------------------------------------------------------

--
-- Table structure for table `user_logs`
--

CREATE TABLE `user_logs` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `user_id` bigint(20) UNSIGNED DEFAULT NULL COMMENT 'کاربر ',
  `action` varchar(255) NOT NULL COMMENT 'فعالیت مربوطه ',
  `ip_address` varchar(255) DEFAULT NULL COMMENT 'ادرس ip کاربر ',
  `user_agent` text DEFAULT NULL COMMENT 'اطلاعات دستگاه کاربر ',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'وضعیت فعالیت true = success, false = failed ',
  `description` text DEFAULT NULL COMMENT 'توضیحات مربوط به فعالت ',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `visits`
--

CREATE TABLE `visits` (
  `id` bigint(20) UNSIGNED NOT NULL COMMENT 'شناسه یکتا بازدید',
  `ip` varchar(255) NOT NULL COMMENT 'آی‌پی بازدیدکننده',
  `page` varchar(255) NOT NULL COMMENT 'شناسه صفحه بازدیدشده',
  `device` varchar(255) NOT NULL COMMENT 'نوع دستگاه (موبایل، دسکتاپ و...)',
  `browser` varchar(255) NOT NULL COMMENT 'مرورگر بازدیدکننده',
  `from_page` varchar(255) NOT NULL COMMENT 'صفحه‌ای که بازدید از آن شروع شده',
  `to_page` varchar(255) NOT NULL COMMENT 'صفحه مقصد بازدید',
  `date` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT 'تاریخ و زمان بازدید',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

